];

export const ServerTable: React.FC = () => {
  const [selectedRows, setSelectedRows] = useState<Set<string>>(new Set());

  const toggleSelectAll = () => {
    if (selectedRows.size === MOCK_DATA.length) {
      setSelectedRows(new Set());
    } else {
      setSelectedRows(new Set(MOCK_DATA.map(d => d.id)));
    }
  };

  const toggleRow = (id: string) => {
    const newSelected = new Set(selectedRows);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedRows(newSelected);
  };

  return (
    <div className="flex-1 overflow-auto bg-white table-container relative">
      <table className="w-full border-collapse table-fixed text-[11px] leading-tight">
        <thead>
          <tr className="bg-gray-50 text-gray-700 uppercase tracking-wider font-medium">
            <th className="w-10 px-2 py-2 border-b border-r border-gray-200 sticky top-0 bg-gray-50 z-10 text-center">
              <input 
                type="checkbox" 
                className="rounded border-gray-300 text-blue-600 focus:ring-blue-500" 
                checked={selectedRows.size === MOCK_DATA.length && MOCK_DATA.length > 0}
                onChange={toggleSelectAll}
              />
            </th>
            {COLUMNS.map((col) => (
              <th 
                key={col.key} 
                className={`${col.width} px-3 py-2 border-b border-r border-gray-200 text-left sticky top-0 bg-gray-50 z-10 hover:bg-gray-100 cursor-pointer group whitespace-nowrap`}
              >
                <div className="flex items-center justify-between">
                  <span>{col.label}</span>
                  <div className="flex flex-col opacity-20 group-hover:opacity-100 transition-opacity">
                    <ChevronUp size={8} className="mb-[-2px]" />
                    <ChevronDown size={8} />
                  </div>
                </div>
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {MOCK_DATA.map((row) => (
            <tr 
              key={row.id} 
              className={`hover:bg-blue-50 transition-colors border-b border-gray-100 ${selectedRows.has(row.id) ? 'bg-blue-50' : ''}`}
            >
              <td className="px-2 py-2 border-r border-gray-200 text-center">
                <input 
                  type="checkbox" 
                  className="rounded border-gray-300 text-blue-600 focus:ring-blue-500" 
                  checked={selectedRows.has(row.id)}
                  onChange={() => toggleRow(row.id)}
                />
              </td>
              {COLUMNS.map((col) => (
                <td key={col.key} className="px-3 py-2 border-r border-gray-200 truncate">
                  {col.isLink ? (
                    <a href="#" className="text-blue-600 hover:underline cursor-pointer">{row[col.key as keyof typeof row]}</a>
                  ) : col.key === 'status' ? (
                    <span className={`${row.status === '正常运行' ? 'text-green-600' : 'text-red-500'} font-medium`}>
                      {row.status}
                    </span>
                  ) : (
                    <span className="text-gray-600">{row[col.key as keyof typeof row]}</span>
                  )}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>

      {/* Background Watermark Simulation */}
      <div className="fixed inset-0 pointer-events-none opacity-[0.03] select-none flex flex-wrap justify-around items-around z-0 overflow-hidden">
        {Array.from({ length: 40 }).map((_, i) => (
          <div key={i} className="transform -rotate-45 text-2xl font-bold p-20">兰义丰 5449</div>
        ))}
      </div>
    </div>
  );
};

