interface ParsedConfig {
  id: string;
  sourceFiles: string[];
  suggestedSNs: string[];
  specs: {
    cpu: string;
    gpu: string;
    memory: string;
    ssd: string;
  };
  models: {
    cpuModel: string;
    gpuModel: string;
    memoryModel: string;
    ssdModel: string;
  };
}

const isAbnormal = (str: string) => {
  const lower = str.toLowerCase();
  return lower.includes('err:') || lower.includes('unknown') || lower.includes('mismatch') || lower.includes('bad');
};

export const ImportModal: React.FC<{ isOpen: boolean; onClose: () => void; onApply: (configs: ParsedConfig[], targetSNs: string[]) => void }> = ({ isOpen, onClose, onApply }) => {
  const [step, setStep] = useState(1);
  const [isParsing, setIsParsing] = useState(false);
  const [parsedConfigs, setParsedConfigs] = useState<ParsedConfig[]>([]);
  const [selectedConfigIds, setSelectedConfigIds] = useState<Set<string>>(new Set());
  const [targetSNInput, setTargetSNInput] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);

  if (!isOpen) return null;

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setIsParsing(true);
    // 模拟离线文件解析过程
    setTimeout(() => {
      const mockParsed: ParsedConfig[] = [
        {
          id: 'config-1',
          sourceFiles: ['pxe_log_001.txt', 'hw_info_001.json'],
          suggestedSNs: ['SN-1001', 'SN-1002'],
          specs: { cpu: 'Intel Xeon 8358 x2', gpu: 'NVIDIA A100 80GB x8', memory: '1024GB', ssd: '3.84TB x4' },
          models: { 
            cpuModel: 'Intel-8358-Standard-V2', 
            gpuModel: 'A100-PG150-S01 x8', 
            memoryModel: 'Samsung-DDR4-3200 x32', 
            ssdModel: 'ERR: Bad Sector Detected' 
          }
        },
        {
          id: 'config-2',
          sourceFiles: ['pxe_log_batch_b.zip'],
          suggestedSNs: ['SN-1005'],
          specs: { cpu: 'Intel Xeon 8350 x2', gpu: '-', memory: '512GB', ssd: '1.92TB x2' },
          models: { 
            cpuModel: 'ERR: Unknown Rev', 
            gpuModel: '-', 
            memoryModel: 'Hynix-DDR4-3200 x16', 
            ssdModel: 'Samsung-PM9A3-V2' 
          }
        }
      ];
      setParsedConfigs(mockParsed);
      setSelectedConfigIds(new Set(mockParsed.map(c => c.id)));
      setIsParsing(false);
      setStep(2);
    }, 1500);
  };

  const updateModel = (configId: string, field: keyof ParsedConfig['models'], value: string) => {
    setParsedConfigs(prev => prev.map(c => c.id === configId ? { ...c, models: { ...c.models, [field]: value } } : c));
  };

  const handleFinish = () => {
    // 收集所有选中的配置和对应的 SN
    const finalConfigs = parsedConfigs.filter(c => selectedConfigIds.has(c.id));
    const targetSNs = targetSNInput.split(/[\s,;]+/).filter(Boolean);
    // 如果输入框为空，默认使用建议的 SN
    const allSNs = targetSNs.length > 0 ? targetSNs : finalConfigs.flatMap(c => c.suggestedSNs);

    onApply(finalConfigs, allSNs);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white w-[1000px] max-h-[85vh] rounded-lg shadow-2xl flex flex-col overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 border-b border-gray-200 bg-gray-50">
          <div className="flex items-center gap-2">
            <div className="p-1.5 bg-blue-100 text-blue-600 rounded">
              <Upload size={16} />
            </div>
            <h3 className="font-semibold text-gray-800 text-sm">导入配置 (PXE/抓取文件解析)</h3>
          </div>
          <button onClick={onClose} className="p-1 hover:bg-gray-200 rounded-full transition-colors">
            <X size={18} className="text-gray-500" />
          </button>
        </div>

        {/* Steps */}
        <div className="flex items-center justify-center py-4 bg-white border-b border-gray-100">
          {[
            { n: 1, l: '解析文件' },
            { n: 2, l: '修正配置' },
            { n: 3, l: '分配资产' }
          ].map((s, i) => (
            <React.Fragment key={s.n}>
              <div className={`flex items-center gap-2 ${step >= s.n ? 'text-blue-600' : 'text-gray-400'}`}>
                <div className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold border-2 ${step >= s.n ? 'border-blue-600 bg-blue-50' : 'border-gray-300'}`}>
                  {step > s.n ? <CheckCircle size={12} /> : s.n}
                </div>
                <span className="text-xs font-medium">{s.l}</span>
              </div>
              {i < 2 && <div className={`w-12 h-0.5 mx-4 ${step > s.n ? 'bg-blue-600' : 'bg-gray-200'}`} />}
            </React.Fragment>
          ))}
        </div>

        {/* Content */}
        <div className="flex-1 overflow-auto p-6 min-h-[400px]">
          {step === 1 && (
            <div className="h-full flex flex-col items-center justify-center border-2 border-dashed border-gray-200 rounded-xl bg-gray-50/50">
              {isParsing ? (
                <div className="flex flex-col items-center gap-4">
                  <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
                  <p className="text-sm text-gray-600 animate-pulse">正在深度解析离线日志并提取硬件 Model...</p>
                </div>
              ) : (
                <>
                  <Upload size={48} className="text-blue-400 mb-4" />
                  <h4 className="text-lg font-medium text-gray-700 mb-2">选择文件夹或 ZIP 压缩包</h4>
                  <p className="text-xs text-gray-400 mb-6 text-center max-w-md">支持上传 PXE 离线抓取的服务器配置 TXT 或 JSON 文件夹。系统将自动聚类识别机型配置。</p>
                  <div className="flex gap-4">
                    <button 
                      onClick={() => fileInputRef.current?.click()}
                      className="px-6 py-2.5 bg-blue-600 text-white rounded-md text-sm font-medium hover:bg-blue-700 shadow-md transition-all active:scale-95"
                    >
                      选择文件/文件夹
                    </button>
                    <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" multiple />
                  </div>
                </>
              )}
            </div>
          )}

          {step === 2 && (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
              <div className="flex items-center justify-between">
                <span className="text-xs text-gray-500">检测到 {parsedConfigs.length} 组独立配置规格</span>
                <span className="text-[10px] text-amber-600 flex items-center gap-1 bg-amber-50 px-2 py-1 rounded border border-amber-100">
                  <AlertTriangle size={12} /> 标记红色的字段检测到异常数据，请核对并修正
                </span>
              </div>

              <div className="space-y-4">
                {parsedConfigs.map((config) => (
                  <div key={config.id} className="border border-gray-200 rounded-lg overflow-hidden bg-white shadow-sm">
                    <div className="bg-gray-50 px-3 py-2 flex items-center justify-between border-b border-gray-200">
                      <div className="flex items-center gap-3">
                        <input 
                          type="checkbox" 
                          checked={selectedConfigIds.has(config.id)}
                          onChange={() => {
                            const next = new Set(selectedConfigIds);
                            next.has(config.id) ? next.delete(config.id) : next.add(config.id);
                            setSelectedConfigIds(next);
                          }}
                          className="rounded text-blue-600"
                        />
                        <span className="text-xs font-bold text-gray-700">配置模板 {config.id.split('-')[1]}</span>
                        <div className="flex gap-1">
                          {config.sourceFiles.map(f => (
                            <span key={f} className="text-[10px] bg-white border border-gray-200 px-1.5 py-0.5 rounded text-gray-500 flex items-center gap-1">
                              <FileText size={10} /> {f}
                            </span>
                          ))}
                        </div>
                      </div>
                    </div>
                    <div className="p-3">
                      <table className="w-full text-[11px] border-collapse">
                        <thead>
                          <tr className="text-gray-400 border-b border-gray-100">
                            <th className="text-left py-1 font-medium w-32">组件</th>
                            <th className="text-left py-1 font-medium w-48">解析规格 (Spec)</th>
                            <th className="text-left py-1 font-medium">Model 号 (可手动修正)</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-50">
                          {Object.keys(config.specs).map((key) => {
                            const field = `${key}Model` as keyof ParsedConfig['models'];
                            const mValue = config.models[field];
                            const isErr = isAbnormal(mValue);
                            return (
                              <tr key={key}>
                                <td className="py-2 font-medium text-gray-500 uppercase">{key}</td>
                                <td className="py-2 text-gray-800">{(config.specs as any)[key]}</td>
                                <td className="py-2">
                                  <div className="relative group">
                                    <input 
                                      type="text"
                                      value={mValue}
                                      onChange={(e) => updateModel(config.id, field, e.target.value)}
                                      className={`w-full px-2 py-1 border rounded focus:outline-none focus:ring-1 ${
                                        isErr 
                                          ? 'bg-red-50 border-red-200 text-red-600 focus:ring-red-500 focus:border-red-500' 
                                          : 'bg-white border-gray-200 focus:ring-blue-500 focus:border-blue-500'
                                      }`}
                                    />
                                    {isErr && <AlertTriangle size={12} className="absolute right-2 top-1.5 text-red-400" />}
                                  </div>
                                </td>
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {step === 3 && (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
              <div className="bg-blue-50 border border-blue-100 rounded-lg p-4">
                <h5 className="text-xs font-bold text-blue-700 mb-2">配置应用设置</h5>
                <p className="text-[11px] text-blue-600 leading-relaxed">
                  系统将把上述修正后的配置规格，批量应用到您指定的服务器 SN 资产中。配置来源将自动标记为“改配”。
                </p>
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-700 mb-2">输入目标服务器 SN (多条请换行或逗号分隔)</label>
                <textarea 
                  value={targetSNInput}
                  onChange={(e) => setTargetSNInput(e.target.value)}
                  placeholder={`例如：\nSN-1001\nSN-1002, SN-1003`}
                  className="w-full h-32 p-3 text-xs font-mono border border-gray-300 rounded focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none"
                />
                <div className="mt-2 flex items-center justify-between">
                  <div className="flex gap-2">
                     <button 
                      onClick={() => setTargetSNInput(parsedConfigs.flatMap(c => c.suggestedSNs).join('\n'))}
                      className="text-[10px] text-blue-600 hover:underline"
                    >
                      使用解析出的建议 SN ({parsedConfigs.flatMap(c => c.suggestedSNs).length}个)
                    </button>
                  </div>
                  <span className="text-[10px] text-gray-400">已输入 {targetSNInput.split(/[\s,;]+/).filter(Boolean).length} 个 SN</span>
                </div>
              </div>

              <div className="border-t border-gray-100 pt-4">
                <h5 className="text-xs font-bold text-gray-700 mb-3">即将覆盖的资产预览</h5>
                <div className="grid grid-cols-4 gap-2">
                   {targetSNInput.split(/[\s,;]+/).filter(Boolean).map(sn => (
                     <div key={sn} className="flex items-center justify-between bg-gray-50 border border-gray-200 px-2 py-1.5 rounded">
                       <span className="text-[10px] font-mono font-bold text-gray-600">{sn}</span>
                       <span className="text-[9px] px-1 bg-green-100 text-green-700 rounded">待更新</span>
                     </div>
                   ))}
                   {targetSNInput === "" && <div className="col-span-4 py-8 text-center text-gray-300 text-xs italic">暂未输入 SN</div>}
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t border-gray-200 bg-gray-50 flex items-center justify-between">
          <div className="text-[11px] text-gray-400">
            {step === 2 && "完成人工核对后，点击下一步分配资产"}
            {step === 3 && "核对 SN 无误后，点击确认完成配置导入"}
          </div>
          <div className="flex gap-3">
            <button 
              onClick={onClose}
              className="px-4 py-2 text-xs font-medium text-gray-600 hover:bg-gray-200 rounded transition-colors"
            >
              取消
            </button>
            {step > 1 && (
              <button 
                onClick={() => setStep(step - 1)}
                className="px-4 py-2 text-xs font-medium text-blue-600 border border-blue-200 rounded hover:bg-blue-50 transition-colors"
              >
                上一步
              </button>
            )}
            {step < 3 ? (
              <button 
                onClick={() => setStep(step + 1)}
                disabled={step === 1}
                className={`flex items-center gap-1.5 px-6 py-2 text-xs font-medium text-white rounded shadow-md transition-all ${step === 1 ? 'bg-gray-300 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-700 active:scale-95'}`}
              >
                下一步 <ChevronRight size={14} />
              </button>
            ) : (
              <button 
                onClick={handleFinish}
                className="flex items-center gap-1.5 px-8 py-2 text-xs font-medium text-white bg-green-600 rounded shadow-md hover:bg-green-700 active:scale-95 transition-all"
              >
                <Save size={14} /> 确认并导入
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

