const isAbnormal = (str: string) => {
  const lower = str.toLowerCase();
  return lower.includes('err:') || lower.includes('unknown') || lower.includes('mismatch') || lower.includes('bad');
};

/**
 * 增强型可编辑单元格组件
 * 支持下拉选择预设值，也支持手动输入自定义内容
 */
const EditableCell: React.FC<{
  value: string;
  options: string[];
  onChange: (val: string) => void;
  placeholder?: string;
  isErrorHighlight?: boolean;
}> = ({ value, options, onChange, placeholder, isErrorHighlight }) => {
  const [isEditingCustom, setIsEditingCustom] = useState(false);
  const isValueInOptions = options.includes(value);

  return (
    <div className="relative flex gap-1 items-center">
      {(!isValueInOptions && value !== "" && !isEditingCustom) || isEditingCustom ? (
        <div className="relative flex-1 group">
          <input
            autoFocus
            type="text"
            value={value}
            onChange={(e) => onChange(e.target.value)}
            onBlur={() => { if (isValueInOptions) setIsEditingCustom(false); }}
            placeholder={placeholder || "手动输入..."}
            className={`w-full px-2 py-1 text-[11px] border rounded focus:outline-none focus:ring-1 ${
              isErrorHighlight && isAbnormal(value)
                ? 'bg-red-50 border-red-300 text-red-600 focus:ring-red-500'
                : 'border-blue-300 focus:ring-blue-500'
            }`}
          />
          <button 
            onClick={() => setIsEditingCustom(false)}
            className="absolute right-1 top-1/2 -translate-y-1/2 p-0.5 text-gray-400 hover:text-blue-500"
            title="切换回选择列表"
          >
            <X size={12} />
          </button>
        </div>
      ) : (
        <div className="relative flex-1 group">
          <select
            value={value}
            onChange={(e) => {
              if (e.target.value === "__CUSTOM__") {
                setIsEditingCustom(true);
              } else {
                onChange(e.target.value);
              }
            }}
            className={`w-full px-2 py-1 pr-6 text-[11px] border rounded appearance-none cursor-pointer focus:outline-none focus:ring-1 ${
              isErrorHighlight && isAbnormal(value)
                ? 'bg-red-50 border-red-200 text-red-600 focus:ring-red-500'
                : 'border-gray-200 focus:ring-blue-500 hover:border-blue-300'
            }`}
          >
            {!isValueInOptions && value !== "" && <option value={value}>{value}</option>}
            {options.map(opt => (
              <option key={opt} value={opt}>{opt}</option>
            ))}
            <option value="__CUSTOM__" className="text-blue-600 font-bold">+ 补充自定义内容...</option>
          </select>
          <div className="absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
            <ChevronDown size={12} />
          </div>
          {isErrorHighlight && isAbnormal(value) && (
            <AlertTriangle size={12} className="absolute right-6 top-1/2 -translate-y-1/2 text-red-400" />
          )}
        </div>
      )}
    </div>
  );
};

