          </div>
          <div className="flex gap-3">
            <button 
              onClick={onClose}
              className="px-4 py-2 text-xs font-medium text-gray-600 hover:bg-gray-200 rounded transition-colors"
            >
              取消
            </button>
            {step > 1 && (
              <button 
                onClick={() => setStep(step - 1)}
                className="px-4 py-2 text-xs font-medium text-blue-600 border border-blue-200 rounded hover:bg-blue-50 transition-colors"
              >
                上一步
              </button>
            )}
            {step < 3 ? (
              <button 
                onClick={() => setStep(step + 1)}
                disabled={step === 1}
                className={`flex items-center gap-1.5 px-6 py-2 text-xs font-medium text-white rounded shadow-md transition-all ${step === 1 ? 'bg-gray-300 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-700 active:scale-95'}`}
