                                    <EditableCell value={specVal} options={opts.specs} onChange={(v) => updateNested(config.id, 'specs', key, v)} />
                                  </td>
                                  <td className="py-2.5">
                                    <EditableCell value={modelVal} options={opts.models} onChange={(v) => updateNested(config.id, 'models', modelKey, v)} isErrorHighlight />
                                  </td>
                                </tr>
                              );
                            })}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

