                          <div className="flex gap-1">
                            {config.sourceFiles.map(f => (
                               <span key={f} className="text-[9px] bg-white text-gray-500 px-1.5 py-0.5 rounded border border-gray-200 flex items-center gap-1 shadow-xs">
                                 <FileText size={8} /> {f}
                               </span>
