  ADD = '添加',
  IMPORT_CONFIG = '导入配置',
  UPDATE = '更新',
  SELECT_ALL = '全选',
  EXPORT = '导出',
  REFRESH = '刷新',
  BATCH_QUERY = '批量查询',
  BATCH_ARRIVAL = '批量到货',
  BATCH_SN = '变更资产编号',
  INIT = '初始化机件信息',
  VNC = '设备是否在建',
  ALLOCATE = '发起分配',
  UPDATE_ACCESSORY = '更新服务器配件Model'
}

