  setFormData: (data: any) => void;
  options: OptionPair[];
}

const HardwareSelect: React.FC<HardwareSelectProps> = ({ label, icon, specKey, modelKey, formData, setFormData, options }) => {
  const currentSpec = formData[specKey] || '';
  const currentModel = formData[modelKey] || '';

  const selectedOption = options.find(o => o.spec === currentSpec);
  const availableModels = selectedOption ? selectedOption.models : [];

  const handleSpecChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const val = e.target.value;
    if (val === 'CUSTOM') return;
    const option = options.find(o => o.spec === val);
    setFormData({
      ...formData,
      [specKey]: val,
      [modelKey]: option ? `${option.models[0]}${option.count > 1 ? ` x${option.count}` : ''}` : ''
    });
  };

  const handleModelChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const val = e.target.value;
    if (val === 'CUSTOM') return;
    const option = options.find(o => o.spec === currentSpec);
    const suffix = (option && option.count > 1) ? ` x${option.count}` : '';
    setFormData({
      ...formData,
      [modelKey]: `${val}${suffix}`
    });
  };

  const checkQuantityConsistency = () => {
    if (!currentSpec || currentSpec === '-') return true;
    const specMatch = currentSpec.match(/x(\d+)/);
    const modelMatch = currentModel.match(/x(\d+)/);
    if (specMatch && modelMatch) return specMatch[1] === modelMatch[1];
    return true;
  };

  const isConsistent = checkQuantityConsistency();

  return (
    <div className="space-y-3 p-4 bg-slate-50/50 rounded-xl border border-gray-100 transition-all hover:shadow-sm group">
      <div className="flex items-center justify-between mb-1">
        <div className="flex items-center gap-2 text-xs font-bold text-gray-700">
          <div className="p-1 bg-white rounded shadow-xs text-blue-500 group-hover:scale-110 transition-transform">
            {icon}
          </div>
          {label}配置
        </div>
        {!isConsistent && (
          <div className="flex items-center gap-1 text-[10px] text-red-500 font-bold animate-pulse">
            <AlertTriangle size={10} /> 数量不一致
          </div>
        )}
      </div>

      <div className="space-y-2">
        <label className="block text-[10px] text-gray-400 uppercase font-bold tracking-tight">规格 (Spec)</label>
        <div className="relative">
          <select 
            value={options.some(o => o.spec === currentSpec) ? currentSpec : 'CUSTOM'}
            onChange={handleSpecChange}
            className="w-full px-3 py-1.5 text-xs border border-gray-200 rounded focus:ring-2 focus:ring-blue-500 outline-none appearance-none bg-white pr-8"
          >
            {options.map(o => <option key={o.spec} value={o.spec}>{o.spec}</option>)}
            <option value="CUSTOM">自定义输入...</option>
          </select>
          <ChevronDown size={12} className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" />
        </div>
        {( !options.some(o => o.spec === currentSpec) || currentSpec === '' ) && (
          <input 
            type="text"
            value={currentSpec}
            onChange={e => setFormData({...formData, [specKey]: e.target.value})}
            placeholder="请输入自定义规格..."
            className="w-full px-3 py-1.5 text-xs border border-blue-200 rounded focus:ring-2 focus:ring-blue-500 outline-none mt-1 bg-blue-50/30 font-medium"
          />
        )}
      </div>

      <div className="space-y-2">
        <label className="block text-[10px] text-gray-400 uppercase font-bold tracking-tight">Model 号 (Model)</label>
        <div className="relative">
          <select 
            disabled={!selectedOption}
            value={availableModels.find(m => currentModel.startsWith(m)) || 'CUSTOM'}
            onChange={handleModelChange}
            className={`w-full px-3 py-1.5 text-xs border border-gray-200 rounded focus:ring-2 focus:ring-blue-500 outline-none appearance-none bg-white pr-8 ${!selectedOption ? 'opacity-50 cursor-not-allowed' : ''}`}
          >
            {availableModels.map(m => <option key={m} value={m}>{m}</option>)}
            <option value="CUSTOM">自定义输入...</option>
          </select>
          <ChevronDown size={12} className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" />
        </div>
        {( !availableModels.some(m => currentModel.startsWith(m)) || currentModel === 'CUSTOM') && (
           <input 
            type="text" 
            value={currentModel} 
            onChange={e => setFormData({...formData, [modelKey]: e.target.value})}
            placeholder="请输入自定义 Model..."
            className="w-full px-3 py-1.5 text-xs border border-gray-200 rounded focus:ring-2 focus:ring-blue-500 outline-none font-mono mt-1"
          />
        )}
      </div>
    </div>
  );
};

