  { id: 'raid', label: 'RAID 阵列卡', icon: <Settings2 size={14} /> },
];

const ASSET_SOURCES: AssetSource[] = ['使用权资产', '算力验收', '短租', '正常采购', '其他'];

// Helper to parse existing string data into structured objects
const parseStringToItems = (specStr: string, modelStr: string): ConfigItem[] => {
  if (!specStr || specStr === '-') return [];
  const specs = specStr.split('|').map(s => s.trim());
  const models = modelStr.split('|').map(m => m.trim());

  return specs.map((s, idx) => {
    const specMatch = s.match(/(.+)\s+x(\d+)/) || [null, s, '1'];
    const modelStrPart = models[idx] || '';
    const modelMatch = modelStrPart.match(/(.+)\s+x(\d+)/) || [null, modelStrPart, '1'];

    return {
      id: Math.random().toString(36).substr(2, 9),
      spec: specMatch[1]?.trim() || s,
      specQty: parseInt(specMatch[2] || '1'),
      model: modelMatch[1]?.trim() || modelStrPart,
      modelQty: parseInt(modelMatch[2] || '1')
    };
  });
};

export const SingleUpdateModal: React.FC<{
  isOpen: boolean;
  onClose: () => void;
  server: ServerAsset | null;
  onSave: (sn: string, updates: Partial<ServerAsset>) => void;
}> = ({ isOpen, onClose, server, onSave }) => {
  const [activeTab, setActiveTab] = useState('cpu');
  const [showConfirm, setShowConfirm] = useState(false);
  const [source, setSource] = useState<AssetSource>('正常采购');
  const [hostname, setHostname] = useState('');
  const [configs, setConfigs] = useState<Record<string, CategoryConfig>>({});

  useEffect(() => {
    if (server) {
      const initialConfigs: Record<string, CategoryConfig> = {};
      CATEGORIES.forEach(cat => {
        const specVal = (server as any)[cat.id] || '';
        const modelVal = (server as any)[`${cat.id}Model`] || '';
        initialConfigs[cat.id] = { items: parseStringToItems(specVal, modelVal) };
      });
      setConfigs(initialConfigs);
      setSource(server.source);
      setHostname(server.hostname);
    }
  }, [server]);

  if (!isOpen || !server) return null;

  const addItem = (catId: string) => {
    const newItem: ConfigItem = {
      id: Math.random().toString(36).substr(2, 9),
      spec: '',
      specQty: 1,
      model: '',
      modelQty: 1
    };
    setConfigs(prev => ({
      ...prev,
      [catId]: { items: [...prev[catId].items, newItem] }
    }));
  };

  const removeItem = (catId: string, itemId: string) => {
    setConfigs(prev => ({
      ...prev,
      [catId]: { items: prev[catId].items.filter(i => i.id !== itemId) }
    }));
  };

  const updateItem = (catId: string, itemId: string, updates: Partial<ConfigItem>) => {
    setConfigs(prev => ({
      ...prev,
      [catId]: {
        items: prev[catId].items.map(i => {
          if (i.id !== itemId) return i;
          const updated = { ...i, ...updates };
          // If spec changes, potentially update model to the first valid one
          if (updates.spec && HARDWARE_CATALOG[catId]) {
            const validModels = HARDWARE_CATALOG[catId].mapping[updates.spec] || [];
            updated.model = validModels[0] || '';
          }
          // Sync quantities if user changes specQty (common workflow)
          if (updates.specQty) updated.modelQty = updates.specQty;
          return updated;
        })
      }
    }));
  };

  const handleFinalSave = () => {
    const finalUpdates: any = { source, hostname };
    CATEGORIES.forEach(cat => {
      const items = configs[cat.id]?.items || [];
      if (items.length === 0) {
        finalUpdates[cat.id] = '-';
        finalUpdates[`${cat.id}Model`] = '-';
      } else {
        finalUpdates[cat.id] = items.map(i => `${i.spec} x${i.specQty}`).join(' | ');
        finalUpdates[`${cat.id}Model`] = items.map(i => `${i.model} x${i.modelQty}`).join(' | ');
      }
    });
    onSave(server.sn, finalUpdates);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300 p-6">
      <div className="bg-white w-full max-w-[1100px] h-[85vh] rounded-3xl shadow-2xl flex flex-col overflow-hidden border border-slate-200">

        {/* Header Section */}
        <div className="px-8 py-6 border-b border-slate-100 bg-slate-50/50 flex items-center justify-between">
          <div className="flex items-center gap-5">
            <div className="w-14 h-14 bg-blue-600 text-white rounded-2xl flex items-center justify-center shadow-xl shadow-blue-100 ring-4 ring-white">
