                            <span className="text-[9px] font-bold text-amber-500 flex items-center gap-1 bg-amber-50 px-2 py-0.5 rounded-full border border-amber-100 animate-pulse">
                              <AlertTriangle size={10} /> 数量不匹配 (当前: {currentModelQtySum})
