                            <CheckCircle size={10} className="text-green-500 opacity-0 group-hover:opacity-100 transition-opacity" />
                          </div>
                        ))}
                      </div>
                      <div className="p-4 border-t border-gray-100 text-[10px] text-gray-400 font-medium text-center">
                        共解析 {config.suggestedSNs.length} 台物理机
                      </div>
                    </div>

                    {/* Content: Spec-Model Mapping */}
                    <div className="flex-1 flex flex-col bg-white">
                      <div className="px-6 py-4 bg-gray-50/30 flex items-center justify-between border-b border-gray-100">
                        <div className="flex items-center gap-3">
                          <input type="checkbox" checked={selectedConfigIds.has(config.id)} onChange={() => {
                            const next = new Set(selectedConfigIds);
                            next.has(config.id) ? next.delete(config.id) : next.add(config.id);
                            setSelectedConfigIds(next);
                          }} className="rounded-lg text-indigo-600 w-5 h-5 cursor-pointer" />
                          <div className="flex flex-col">
                            <span className="text-xs font-bold text-gray-800 uppercase tracking-tight">模版编号: {config.id}</span>
                            <div className="flex gap-2 mt-0.5">
                              {config.sourceFiles.map(f => (
                                <span key={f} className="text-[9px] text-gray-400 flex items-center gap-1"><FileText size={8} /> {f}</span>
                              ))}
                            </div>
                          </div>
                        </div>
                      </div>

                      <div className="p-8">
                        <div className="grid grid-cols-12 gap-4 mb-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest px-2">
                          <div className="col-span-2">硬件类别</div>
                          <div className="col-span-10">配置映射 (规格 Specification → 对应 Model)</div>
                        </div>
                        <div className="space-y-3">
                          {CATEGORIES.map((cat) => {
                            const specVal = config.specs[cat.id] || '-';
                            const modelKey = `${cat.id}Model`;
                            const modelVal = config.models[modelKey] || '-';
                            const opts = ENUM_OPTIONS[cat.id] || { specs: [], models: [] };
                            const hasErr = isAbnormal(specVal) || isAbnormal(modelVal);

                            return (
                              <div key={cat.id} className={`grid grid-cols-12 items-center p-3 rounded-2xl border transition-all ${hasErr ? 'bg-rose-50/30 border-rose-200 shadow-sm' : 'hover:bg-slate-50 border-gray-100'}`}>
                                <div className="col-span-2 flex items-center gap-2.5">
                                  <div className="p-2 bg-white rounded-xl shadow-sm border border-gray-100">{cat.icon}</div>
                                  <span className="text-[11px] font-bold text-gray-600">{cat.label}</span>
                                </div>

                                <div className="col-span-10 flex items-center gap-4">
                                  {/* Visual indication of mapping relationship */}
                                  <div className="flex-1">
                                    <EditableCell 
                                      value={specVal} 
                                      options={opts.specs} 
                                      onChange={(v) => updateNested(config.id, 'specs', cat.id, v)}
                                      placeholder="识别规格..."
                                    />
                                  </div>

                                  <div className="shrink-0 flex items-center justify-center">
                                    <div className={`p-1.5 rounded-full ${hasErr ? 'bg-rose-100 text-rose-500' : 'bg-indigo-50 text-indigo-400'}`}>
                                      <ArrowRight size={14} />
                                    </div>
                                  </div>

                                  <div className="flex-1">
                                    <EditableCell 
                                      value={modelVal} 
                                      options={opts.models} 
                                      onChange={(v) => updateNested(config.id, 'models', modelKey, v)} 
                                      placeholder="识别 Model 号..."
                                      isMono
                                    />
                                  </div>

                                  {hasErr && (
                                    <div className="shrink-0 animate-pulse text-rose-500" title="识别到异常数据">
                                      <AlertTriangle size={16} />
                                    </div>
                                  )}
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {step === 3 && (
            <div className="space-y-8 animate-in slide-in-from-right-4 duration-400">
              <div className="grid grid-cols-1 gap-8">
                {selectedConfigs.length === 0 ? (
                  <div className="py-24 text-center text-gray-400 flex flex-col items-center gap-4">
                    <Layers size={48} className="opacity-20" />
                    <p className="italic text-sm">请在“核对”环节选择要应用的配置模版</p>
                  </div>
                ) : selectedConfigs.map((config) => (
                  <div key={config.id} className="bg-white border border-gray-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100">
                    <div className="flex items-center justify-between mb-6 pb-4 border-b border-slate-50">
                      <div className="flex items-center gap-4">
                        <div className="w-3 h-8 bg-indigo-600 rounded-full" />
                        <div>
                          <h5 className="text-base font-bold text-gray-900">批量 SN 分配 (模版: {config.id})</h5>
                          <p className="text-[10px] text-gray-400 mt-0.5">将该配置快照同步至以下服务器</p>
                        </div>
                      </div>
                    </div>

                    <div className="flex gap-8">
                      <div className="flex-1">
                        <div className="flex items-center justify-between mb-3">
                          <label className="text-[11px] font-bold text-gray-500 uppercase tracking-widest px-2">目标资产序列号</label>
                          <button 
                            onClick={() => { setCurrentActiveConfigId(config.id); snFileInputRef.current?.click(); }}
                            className="text-[11px] font-bold text-indigo-600 hover:text-indigo-700 bg-indigo-50 px-3 py-1.5 rounded-xl border border-indigo-100 flex items-center gap-2 transition-all active:scale-95"
                          >
                            <FileUp size={14} /> 批量导入 SN (.txt)
                          </button>
                        </div>
                        <textarea 
                          value={config.targetSNs.join('\n')}
                          onChange={(e) => updateConfig(config.id, { targetSNs: e.target.value.split(/[\s,;]+/).filter(Boolean) })}
                          placeholder="请输入或导入目标服务器 SN..."
                          className="w-full h-40 p-5 text-xs font-mono border border-gray-200 rounded-3xl focus:ring-4 focus:ring-indigo-100 focus:border-indigo-400 outline-none resize-none transition-all shadow-inner bg-slate-50/30"
                        />
                        <div className="mt-4 flex justify-between items-center px-2">
                          <button 
                            onClick={() => updateConfig(config.id, { targetSNs: [...config.suggestedSNs] })}
                            className="text-[11px] font-bold text-indigo-600 hover:underline flex items-center gap-1.5"
                          >
                            <ListFilter size={14} /> 采用自动识别出的 SN ({config.suggestedSNs.length}台)
                          </button>
                          <span className="text-[10px] font-bold text-gray-400 bg-gray-100 px-3 py-1 rounded-full border border-gray-200">
                            待处理总计: <span className="text-indigo-600">{config.targetSNs.length}</span> 台
                          </span>
                        </div>
                      </div>

                      <div className="w-80 bg-slate-50/50 rounded-3xl p-5 border border-slate-100 shadow-inner flex flex-col">
                        <h6 className="text-[10px] font-bold text-gray-400 mb-4 uppercase tracking-widest text-center">待改配清单预览</h6>
                        <div className="flex-1 space-y-2 overflow-y-auto max-h-48 pr-2 custom-scrollbar">
                          {config.targetSNs.map(sn => (
                            <div key={sn} className="flex items-center justify-between bg-white px-4 py-2.5 rounded-2xl border border-gray-100 shadow-sm animate-in fade-in duration-300">
                              <span className="text-[11px] font-mono font-bold text-gray-700">{sn}</span>
                              <CheckCircle size={12} className="text-emerald-500" />
                            </div>
                          ))}
                          {config.targetSNs.length === 0 && <div className="text-center py-12 text-[11px] text-gray-300 italic">暂无目标 SN 数据</div>}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
                <input type="file" ref={snFileInputRef} className="hidden" accept=".txt,.csv" onChange={(e) => currentActiveConfigId && handleSNFileUpload(e, currentActiveConfigId)} />
              </div>
            </div>
          )}
        </div>

        {/* Footer Actions */}
        <div className="px-10 py-6 border-t border-gray-100 bg-gray-50/50 flex items-center justify-between">
          <div className="flex items-center gap-3 text-gray-400">
            <AlertTriangle size={16} className="text-amber-500" />
            <span className="text-[10px] font-medium leading-relaxed uppercase tracking-tight">
              提交后将按 <b>Spec-Model 映射</b> 更新服务器配置。<br/>
              系统将自动记录审计日志，并将对应 SN 状态同步至 <span className="text-indigo-600 font-bold">“改配”</span>。
            </span>
          </div>
          <div className="flex gap-4">
            <button onClick={onClose} className="px-8 py-3 text-xs font-bold text-gray-500 hover:bg-slate-200 rounded-2xl transition-all">取消</button>
            {step > 1 && (
              <button onClick={() => setStep(step - 1)} className="px-8 py-3 text-xs font-bold text-indigo-600 border border-indigo-200 rounded-2xl hover:bg-indigo-50 transition-all">
                上一步
              </button>
            )}
            {step < 3 ? (
              <button 
                onClick={() => setStep(step + 1)} 
                disabled={step === 1 && !isParsing}
                className={`flex items-center gap-2 px-12 py-3 text-xs font-bold text-white rounded-2xl shadow-xl transition-all ${step === 1 && !isParsing ? 'bg-gray-300 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-700 active:scale-95 shadow-indigo-100'}`}
              >
                继续核对 <ChevronRight size={16} />
              </button>
            ) : (
              <button 
                onClick={() => { onApply(selectedConfigs); onClose(); }} 
                className="flex items-center gap-2 px-14 py-3 text-xs font-bold text-white bg-green-600 rounded-2xl shadow-xl shadow-green-100 hover:bg-green-700 active:scale-95 transition-all"
              >
                <Save size={16} /> 确认并同步应用
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useMemo } from 'react';
import { X, Upload, FileText, CheckCircle, AlertTriangle, ChevronRight, Save, ChevronDown, ListFilter, Cpu, HardDrive, Layout, Server, FileUp, ArrowRight, Layers, Settings2, Link, Database, Search } from 'lucide-react';

export interface ParsedConfig {
  id: string;
  sourceFiles: string[];
  suggestedSNs: string[];
  targetSNs: string[]; 
  rawIds: Record<string, string>; // The PART ID / FRU found in the log
  specs: Record<string, string>;
  models: Record<string, string>;
}

const ENUM_OPTIONS: Record<string, { specs: string[]; models: string[] }> = {
  gpu: {
    specs: ['NVIDIA A100 80GB x8', 'NVIDIA H100 80GB x8', 'NVIDIA L40S x4'],
    models: ['A100-PG150-S01 x8', 'H100-PG520-S01 x8', 'L40S-NVLink-V1']
  },
  cpu: {
    specs: ['Intel Xeon 8358 x2', 'Intel Xeon Platinum 8480C x2', 'AMD EPYC 9654 x2'],
    models: ['Intel-8358-Standard-V2', 'Intel-8480C-QS', 'AMD-EPYC-9654-Retail']
  },
  memory: {
    specs: ['256GB (32GB x8)', '1024GB (64GB x16)'],
    models: ['Samsung-DDR4-3200 x8', 'Hynix-DDR5-4800 x16']
  },
  networkCard: {
    specs: ['100G Dual Port x1', '25G Quad Port x1'],
    models: ['Mellanox-CX6-VPI', 'Mellanox-CX4-LX']
  },
  harddisk: {
    specs: ['2TB SATA x2', '8TB SAS x12'],
    models: ['ST2000-NM001', 'Seagate-Exos-X18']
  },
  ssd: {
    specs: ['3.84TB NVMe x2', '7.68TB NVMe x1'],
    models: ['Samsung-PM1733', 'Micron-7450-Pro']
  },
  raid: {
    specs: ['RAID 1', 'RAID 10'],
    models: ['9460-16i-Primary', '9361-8i-Adapter']
  },
  fpga: {
    specs: ['Xilinx Alveo U250 x1'],
    models: ['U250-PQ123']
  }
};

const CATEGORIES = [
  { id: 'gpu', label: 'GPU', icon: <Layout size={12} className="text-indigo-400" /> },
  { id: 'cpu', label: 'CPU', icon: <Cpu size={12} className="text-blue-400" /> },
  { id: 'memory', label: '内存', icon: <Settings2 size={12} className="text-purple-400" /> },
  { id: 'networkCard', label: '网卡', icon: <Layout size={12} className="text-emerald-400" /> },
  { id: 'harddisk', label: '硬盘', icon: <HardDrive size={12} className="text-amber-400" /> },
  { id: 'ssd', label: 'SSD', icon: <HardDrive size={12} className="text-teal-400" /> },
  { id: 'raid', label: 'RAID', icon: <Settings2 size={12} className="text-slate-400" /> },
  { id: 'fpga', label: 'FPGA', icon: <Cpu size={12} className="text-rose-400" /> },
];

const isAbnormal = (str: string) => {
  if (!str || str.trim() === '' || str.trim() === '-') return false;
  const lower = str.toLowerCase();
  return lower.includes('err:') || lower.includes('unknown') || lower.includes('mismatch') || lower.includes('bad');
};

const EditableCell: React.FC<{
  value: string;
  options: string[];
  onChange: (val: string) => void;
  placeholder?: string;
  isMono?: boolean;
}> = ({ value, options, onChange, placeholder = "请选择...", isMono }) => {
  const [isCustom, setIsCustom] = useState(!options.includes(value) && value !== "");
  const abnormal = isAbnormal(value);

  return (
    <div className="relative flex-1">
      {isCustom ? (
        <div className="relative">
          <input
            autoFocus
            type="text"
            value={value}
            onChange={(e) => onChange(e.target.value)}
            className={`w-full px-3 py-1.5 text-[11px] border rounded-lg focus:outline-none focus:ring-2 pr-7 transition-all ${
              abnormal ? 'bg-rose-50 border-rose-300 text-rose-700 focus:ring-rose-200' : 'bg-white border-blue-200 focus:ring-blue-100'
            } ${isMono ? 'font-mono' : ''}`}
          />
          <button onClick={() => setIsCustom(false)} className="absolute right-1 top-1/2 -translate-y-1/2 p-1 text-gray-400 hover:text-blue-500">
            <X size={10} />
          </button>
        </div>
      ) : (
        <div className="relative">
          <select
            value={value}
            onChange={(e) => e.target.value === "__CUSTOM__" ? setIsCustom(true) : onChange(e.target.value)}
            className={`w-full px-3 py-1.5 pr-6 text-[11px] border rounded-lg appearance-none cursor-pointer focus:outline-none focus:ring-2 transition-all ${
              abnormal ? 'bg-rose-50 border-rose-200 text-rose-600 focus:ring-rose-100 font-bold' : 'bg-white border-gray-200 focus:ring-blue-100 hover:border-blue-300'
            } ${isMono ? 'font-mono' : ''}`}
          >
            <option value="" disabled>{placeholder}</option>
            {options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            {!options.includes(value) && value !== "" && <option value={value}>{value}</option>}
            <option value="__CUSTOM__" className="text-blue-600 font-bold">+ 自定义输入</option>
          </select>
          <div className="absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
            <ChevronDown size={12} />
          </div>
        </div>
      )}
    </div>
  );
};

export const ImportModal: React.FC<{ isOpen: boolean; onClose: () => void; onApply: (configs: ParsedConfig[]) => void }> = ({ isOpen, onClose, onApply }) => {
  const [step, setStep] = useState(1);
  const [isParsing, setIsParsing] = useState(false);
  const [parsedConfigs, setParsedConfigs] = useState<ParsedConfig[]>([]);
  const [selectedConfigIds, setSelectedConfigIds] = useState<Set<string>>(new Set());
  const fileInputRef = useRef<HTMLInputElement>(null);
  const snFileInputRef = useRef<HTMLInputElement>(null);
  const [currentActiveConfigId, setCurrentActiveConfigId] = useState<string | null>(null);

  const selectedConfigs = useMemo(() => parsedConfigs.filter(c => selectedConfigIds.has(c.id)), [parsedConfigs, selectedConfigIds]);

  if (!isOpen) return null;

  const handleFileUpload = () => {
    setIsParsing(true);
    setTimeout(() => {
      const mockParsed: ParsedConfig[] = [
        {
          id: 'CFG-2024-001',
          sourceFiles: ['pxe_log_node1.txt'],
          suggestedSNs: ['SN-1001', 'SN-1002'],
          targetSNs: ['SN-1001', 'SN-1002'],
          rawIds: {
            gpu: 'NV-ID-A100-SXM4',
            cpu: 'GenuineIntel-Family-6-Model-106',
            memory: 'PN: M393A4K40CB2-CT7',
            networkCard: 'PCI-15B3-1017',
            harddisk: 'ST2000NM001',
            ssd: 'NULL_PART_ID',
            raid: 'AVAGO-MegaRAID-9460',
            fpga: '-'
          },
          specs: {
            gpu: 'NVIDIA A100 80GB x8',
            cpu: 'Intel Xeon 8358 x2',
            memory: '1024GB (64GB x16)',
            networkCard: '100G Dual Port x1',
            harddisk: '2TB SATA x2',
            ssd: '-',
            raid: 'RAID 1',
            fpga: '-'
          },
          models: {
            gpuModel: 'A100-PG150-S01 x8',
            cpuModel: 'Intel-8358-Standard-V2',
            memoryModel: 'Samsung-DDR4-3200 x16',
            networkCardModel: 'Mellanox-CX6-VPI',
            harddiskModel: 'ST2000-NM001 x2',
            ssdModel: 'ERR: Part Not Found',
            raidModel: '9460-16i-Primary',
            fpgaModel: '-'
          }
        }
      ];
      setParsedConfigs(mockParsed);
      setSelectedConfigIds(new Set(mockParsed.map(c => c.id)));
      setIsParsing(false);
      setStep(2);
    }, 1200);
  };

  const handleSNFileUpload = (e: React.ChangeEvent<HTMLInputElement>, configId: string) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const sns = (event.target?.result as string).split(/[\s,;]+/).filter(Boolean);
      updateConfig(configId, { targetSNs: sns });
      e.target.value = '';
    };
    reader.readAsText(file);
  };

  const updateConfig = (id: string, updates: Partial<ParsedConfig>) => {
    setParsedConfigs(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const updateNested = (id: string, type: 'specs' | 'models', field: string, value: string) => {
    setParsedConfigs(prev => prev.map(c => c.id === id ? { ...c, [type]: { ...(c[type] as any), [field]: value } } : c));
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white w-[1250px] max-h-[94vh] rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden border border-white">
        {/* Header */}
        <div className="px-10 py-7 border-b border-gray-100 bg-gray-50/50 flex items-center justify-between">
          <div className="flex items-center gap-5">
            <div className="p-4 bg-indigo-600 text-white rounded-3xl shadow-xl shadow-indigo-100">
              <Upload size={24} />
            </div>
            <div>
              <h3 className="font-bold text-gray-900 text-lg">导入配置文件</h3>
              <p className="text-[12px] text-gray-500 font-medium">系统将自动核对抓取数据 (Part ID) 与库中对应的规格 (Spec) 和型号 (Model)</p>
            </div>
          </div>
          <button onClick={onClose} className="p-2.5 hover:bg-gray-200 rounded-full text-gray-400 transition-colors"><X size={24} /></button>
        </div>

        {/* Steps Navigation */}
        <div className="flex bg-white px-16 py-6 border-b border-gray-50 shadow-sm justify-between">
          {[
            { n: 1, l: '文件解析' },
            { n: 2, l: '规格与 Model 映射核对' },
            { n: 3, l: '资产应用' }
          ].map((s, i) => (
            <React.Fragment key={s.n}>
              <div className={`flex items-center gap-4 ${step >= s.n ? 'text-indigo-600' : 'text-gray-300'}`}>
                <div className={`w-9 h-9 rounded-full flex items-center justify-center text-sm font-bold transition-all ${step >= s.n ? 'bg-indigo-600 text-white shadow-lg' : 'bg-gray-100 border border-gray-200'}`}>{s.n}</div>
                <span className="text-[13px] font-bold whitespace-nowrap">{s.l}</span>
              </div>
              {i < 2 && <div className={`flex-1 mx-12 h-0.5 mt-4.5 transition-colors ${step > s.n ? 'bg-indigo-600' : 'bg-gray-100'}`} />}
            </React.Fragment>
          ))}
        </div>

        {/* Main Content Area */}
        <div className="flex-1 overflow-auto p-12 bg-slate-50/20 custom-scrollbar min-h-[550px]">
          {step === 1 && (
            <div className="h-full flex flex-col items-center justify-center">
              {isParsing ? (
                <div className="text-center animate-pulse">
                  <div className="w-20 h-20 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto mb-8" />
                  <p className="text-base font-bold text-gray-600 tracking-tight">正在多层级匹配 Part ID，建立硬件拓扑图...</p>
                </div>
              ) : (
                <div 
                  className="w-full max-w-3xl p-24 border-2 border-dashed border-gray-200 rounded-[4rem] bg-white flex flex-col items-center hover:border-indigo-400 hover:bg-indigo-50/30 transition-all cursor-pointer group shadow-sm"
                  onClick={() => fileInputRef.current?.click()}
                >
                  <div className="w-24 h-24 bg-indigo-50 text-indigo-500 rounded-[2.5rem] flex items-center justify-center mb-8 group-hover:scale-110 transition-transform">
                    <FileUp size={48} />
                  </div>
                  <h4 className="text-2xl font-bold text-gray-800">上传离线抓取文件</h4>
                  <p className="text-sm text-gray-400 mt-4 text-center leading-relaxed">支持单文件或多文件解析。系统将基于库中的 FRU/Part ID 自动推导出型号和规格。</p>
                  <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" multiple />
                </div>
              )}
            </div>
          )}

          {step === 2 && (
            <div className="space-y-10 animate-in slide-in-from-right-4 duration-400">
              <div className="flex items-center justify-between bg-amber-50 border border-amber-100 p-5 rounded-[2rem] shadow-sm">
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 bg-amber-100 text-amber-600 rounded-2xl flex items-center justify-center">
                    <Database size={20} />
                  </div>
                  <div>
                    <span className="text-sm font-bold text-amber-800 block">映射库核对状态</span>
                    <span className="text-[11px] text-amber-600 font-medium">
                      逻辑路径: <span className="font-bold">抓取 Part ID</span> → <span className="underline">数据库匹配</span> → <span className="font-bold">对应型号/规格</span>
                    </span>
                  </div>
                </div>
                <div className="px-4 py-2 bg-white rounded-2xl border border-gray-100 flex items-center gap-2 text-[11px] font-bold text-gray-500">
                  <Search size={14} className="text-amber-500" />
                  解析到 {parsedConfigs.length} 组独立硬件环境
                </div>
              </div>

              <div className="space-y-10">
                {parsedConfigs.map((config) => (
                  <div key={config.id} className="bg-white border border-gray-200 rounded-[3rem] overflow-hidden shadow-2xl shadow-slate-200/50 flex">
                    {/* Sidebar: SN Info */}
                    <div className="w-64 bg-gray-50/50 border-r border-gray-100 flex flex-col">
                      <div className="px-6 py-5 bg-gray-100/50 border-b border-gray-200 flex items-center gap-3">
                        <Server size={16} className="text-gray-400" />
                        <span className="text-[12px] font-bold text-gray-700">覆盖资产 (SN 抽检)</span>
                      </div>
                      <div className="p-5 flex-1 overflow-y-auto max-h-[500px] space-y-2.5 custom-scrollbar">
                        {config.suggestedSNs.map(sn => (
                          <div key={sn} className="bg-white border border-gray-200 px-4 py-2 rounded-2xl text-[11px] font-mono text-gray-600 shadow-sm flex items-center justify-between group">
                            {sn}
                            <CheckCircle size={12} className="text-green-500 opacity-0 group-hover:opacity-100 transition-opacity" />
                          </div>
                        ))}
                      </div>
                      <div className="p-5 border-t border-gray-100 text-[11px] text-gray-400 font-bold text-center">
                        共解析 {config.suggestedSNs.length} 台物理机
                      </div>
                    </div>

                    {/* Content: Mapping Logic */}
                    <div className="flex-1 flex flex-col bg-white">
                      <div className="px-8 py-5 bg-gray-50/30 flex items-center justify-between border-b border-gray-100">
                        <div className="flex items-center gap-4">
                          <input type="checkbox" checked={selectedConfigIds.has(config.id)} onChange={() => {
                            const next = new Set(selectedConfigIds);
                            next.has(config.id) ? next.delete(config.id) : next.add(config.id);
                            setSelectedConfigIds(next);
                          }} className="rounded-xl text-indigo-600 w-6 h-6 cursor-pointer" />
                          <div className="flex flex-col">
                            <span className="text-sm font-bold text-gray-800 tracking-tight">解析模版: {config.id}</span>
                            <span className="text-[10px] text-gray-400 font-medium">源文件: {config.sourceFiles.join(', ')}</span>
                          </div>
                        </div>
                      </div>

                      <div className="p-10">
                        <div className="grid grid-cols-12 gap-4 mb-6 text-[11px] font-bold text-gray-400 uppercase tracking-widest px-4">
                          <div className="col-span-2">配件类别</div>
                          <div className="col-span-10 grid grid-cols-11 gap-4">
                            <div className="col-span-3">抓取数据 (Part ID)</div>
                            <div className="col-span-1"></div>
                            <div className="col-span-3">匹配型号 (Model)</div>
                            <div className="col-span-1"></div>
                            <div className="col-span-3">对应规格 (Specification)</div>
                          </div>
                        </div>

                        <div className="space-y-4">
                          {CATEGORIES.map((cat) => {
                            const rawId = config.rawIds[cat.id] || '-';
                            const specVal = config.specs[cat.id] || '-';
                            const modelKey = `${cat.id}Model`;
                            const modelVal = config.models[modelKey] || '-';
                            const opts = ENUM_OPTIONS[cat.id] || { specs: [], models: [] };

                            const isUnknownId = rawId === 'NULL_PART_ID' || rawId === '-';
                            const isModelErr = isAbnormal(modelVal);
                            const isSpecErr = isAbnormal(specVal);
                            const hasErr = isUnknownId || isModelErr || isSpecErr;

                            return (
                              <div key={cat.id} className={`grid grid-cols-12 items-center p-4 rounded-[2rem] border transition-all ${hasErr ? 'bg-rose-50/30 border-rose-200' : 'hover:bg-slate-50 border-gray-100'}`}>
                                <div className="col-span-2 flex items-center gap-3">
                                  <div className={`p-2.5 rounded-2xl shadow-sm border ${hasErr ? 'bg-rose-100 border-rose-200 text-rose-500' : 'bg-white border-gray-100'}`}>
                                    {cat.icon}
                                  </div>
                                  <span className="text-[12px] font-bold text-gray-600">{cat.label}</span>
                                </div>

                                <div className="col-span-10 grid grid-cols-11 items-center gap-4">
                                  {/* Part ID from Log */}
                                  <div className="col-span-3">
                                    <div className={`px-3 py-2 rounded-xl border text-[10px] font-mono font-bold truncate ${isUnknownId ? 'bg-rose-50 border-rose-300 text-rose-500' : 'bg-slate-100 border-slate-200 text-slate-600'}`}>
                                      {rawId}
                                    </div>
                                    <div className="mt-1 px-1 flex items-center justify-between">
                                      <span className="text-[9px] font-bold text-gray-400 uppercase tracking-tighter">源 Part ID</span>
                                      {isUnknownId ? (
                                        <span className="text-[8px] px-1 bg-rose-500 text-white rounded font-bold">未找到</span>
                                      ) : (
                                        <span className="text-[8px] px-1 bg-emerald-500 text-white rounded font-bold">已解析</span>
                                      )}
                                    </div>
                                  </div>

                                  {/* Connection 1 */}
                                  <div className="col-span-1 flex justify-center">
                                    <div className={`p-1.5 rounded-full ${hasErr ? 'text-rose-400' : 'text-indigo-300'}`}>
                                      <ArrowRight size={14} />
                                    </div>
                                  </div>

                                  {/* Matched Model */}
                                  <div className="col-span-3">
                                    <EditableCell 
                                      value={modelVal} 
                                      options={opts.models} 
                                      onChange={(v) => updateNested(config.id, 'models', modelKey, v)} 
                                      placeholder="未找到 Model"
                                      isMono
                                    />
                                    <div className="mt-1 px-1 text-[9px] font-bold text-gray-400 uppercase tracking-tighter">关联型号</div>
                                  </div>

                                  {/* Connection 2 */}
                                  <div className="col-span-1 flex justify-center">
                                    <div className={`p-1.5 rounded-full ${hasErr ? 'text-rose-400' : 'text-indigo-300'}`}>
                                      <ArrowRight size={14} />
                                    </div>
                                  </div>

                                  {/* Derived Specification */}
                                  <div className="col-span-3">
                                    <EditableCell 
                                      value={specVal} 
                                      options={opts.specs} 
                                      onChange={(v) => updateNested(config.id, 'specs', cat.id, v)}
                                      placeholder="未匹配规格"
                                    />
                                    <div className="mt-1 px-1 text-[9px] font-bold text-gray-400 uppercase tracking-tighter">对应层级规格</div>
                                  </div>
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {step === 3 && (
            <div className="space-y-10 animate-in slide-in-from-right-4 duration-400">
              <div className="grid grid-cols-1 gap-10">
                {selectedConfigs.length === 0 ? (
                  <div className="py-32 text-center text-gray-400 flex flex-col items-center gap-6">
                    <Layers size={64} className="opacity-20" />
                    <p className="italic text-base font-medium">请在核对环节勾选已通过验证的模版</p>
                  </div>
                ) : selectedConfigs.map((config) => (
                  <div key={config.id} className="bg-white border border-gray-200 rounded-[3.5rem] p-12 shadow-2xl shadow-slate-100">
                    <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-50">
                      <div className="flex items-center gap-5">
                        <div className="w-4 h-10 bg-indigo-600 rounded-full" />
                        <div>
                          <h5 className="text-xl font-bold text-gray-900">批量应用资产 (模版: {config.id})</h5>
                          <p className="text-[12px] text-gray-400 mt-1 font-medium">配置快照将同步至以下服务器序列号</p>
                        </div>
                      </div>
                    </div>

                    <div className="flex gap-12">
                      <div className="flex-1">
                        <div className="flex items-center justify-between mb-4">
                          <label className="text-[12px] font-bold text-gray-500 uppercase tracking-widest px-3">目标服务器 SN</label>
                          <button 
                            onClick={() => { setCurrentActiveConfigId(config.id); snFileInputRef.current?.click(); }}
                            className="text-[12px] font-bold text-indigo-600 hover:text-indigo-700 bg-indigo-50 px-4 py-2 rounded-2xl border border-indigo-100 flex items-center gap-2 transition-all active:scale-95 shadow-sm shadow-indigo-50"
                          >
                            <FileUp size={16} /> 导入 SN 文件
                          </button>
                        </div>
                        <textarea 
                          value={config.targetSNs.join('\n')}
                          onChange={(e) => updateConfig(config.id, { targetSNs: e.target.value.split(/[\s,;]+/).filter(Boolean) })}
                          placeholder="请输入目标服务器 SN..."
                          className="w-full h-48 p-6 text-sm font-mono border border-gray-200 rounded-[2.5rem] focus:ring-4 focus:ring-indigo-100 focus:border-indigo-400 outline-none resize-none transition-all shadow-inner bg-slate-50/20"
                        />
                        <div className="mt-5 flex justify-between items-center px-4">
                          <button 
                            onClick={() => updateConfig(config.id, { targetSNs: [...config.suggestedSNs] })}
                            className="text-[12px] font-bold text-indigo-600 hover:underline flex items-center gap-2"
                          >
                            <ListFilter size={16} /> 采用核对出的 SN ({config.suggestedSNs.length}台)
                          </button>
                          <span className="text-[11px] font-bold text-gray-400 bg-gray-100 px-4 py-1.5 rounded-full border border-gray-200">
                            待改配资产数: <span className="text-indigo-600">{config.targetSNs.length}</span>
                          </span>
                        </div>
                      </div>

                      <div className="w-96 bg-slate-50/50 rounded-[3rem] p-7 border border-slate-100 shadow-inner flex flex-col">
                        <h6 className="text-[11px] font-bold text-gray-400 mb-5 uppercase tracking-widest text-center">即将更新的 SN 队列</h6>
                        <div className="flex-1 space-y-2.5 overflow-y-auto max-h-56 pr-3 custom-scrollbar">
                          {config.targetSNs.map(sn => (
                            <div key={sn} className="flex items-center justify-between bg-white px-5 py-3 rounded-2xl border border-gray-100 shadow-sm animate-in fade-in duration-300">
                              <span className="text-[12px] font-mono font-bold text-gray-700">{sn}</span>
                              <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse" />
                            </div>
                          ))}
                          {config.targetSNs.length === 0 && <div className="text-center py-16 text-xs text-gray-300 italic">暂无 SN 数据</div>}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
                <input type="file" ref={snFileInputRef} className="hidden" accept=".txt,.csv" onChange={(e) => currentActiveConfigId && handleSNFileUpload(e, currentActiveConfigId)} />
              </div>
            </div>
          )}
        </div>

        {/* Footer Actions */}
        <div className="px-12 py-7 border-t border-gray-100 bg-gray-50/50 flex items-center justify-between">
          <div className="flex items-center gap-4 text-gray-400">
            <AlertTriangle size={20} className="text-amber-500" />
            <span className="text-[11px] font-bold leading-relaxed uppercase tracking-tight">
              同步后，系统将建立 <span className="text-slate-800 font-black">Part ID → Model → Spec</span> 的审计快照。<br/>
              如果库中 Part ID 缺失，建议在核对阶段手动补齐映射关系。
            </span>
          </div>
          <div className="flex gap-5">
            <button onClick={onClose} className="px-10 py-3.5 text-xs font-bold text-gray-500 hover:bg-slate-200 rounded-[1.5rem] transition-all">取消退出</button>
            {step > 1 && (
              <button onClick={() => setStep(step - 1)} className="px-10 py-3.5 text-xs font-bold text-indigo-600 border border-indigo-200 rounded-[1.5rem] hover:bg-indigo-50 transition-all">
                上一步核对
              </button>
            )}
            {step < 3 ? (
              <button 
                onClick={() => setStep(step + 1)} 
                disabled={step === 1 && !isParsing}
                className={`flex items-center gap-2 px-14 py-3.5 text-xs font-bold text-white rounded-[1.5rem] shadow-2xl transition-all ${step === 1 && !isParsing ? 'bg-gray-300 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-700 active:scale-95 shadow-indigo-100'}`}
              >
                下一步: 批量核对 <ChevronRight size={18} />
              </button>
            ) : (
              <button 
                onClick={() => { onApply(selectedConfigs); onClose(); }} 
                className="flex items-center gap-2 px-16 py-3.5 text-xs font-bold text-white bg-green-600 rounded-[1.5rem] shadow-2xl shadow-green-100 hover:bg-green-700 active:scale-95 transition-all"
              >
                <Save size={18} /> 确认同步至资产
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useMemo } from 'react';
import { X, Upload, FileText, CheckCircle, AlertTriangle, ChevronRight, Save, ChevronDown, ListFilter, Cpu, HardDrive, Layout, Server, FileUp, ArrowRight, Layers, Settings2, Database, Search, Hash } from 'lucide-react';

export interface ParsedConfig {
  id: string;
  sourceFiles: string[];
  suggestedSNs: string[];
  targetSNs: string[]; 
  rawIds: Record<string, string>; // The PART ID / FRU found in the log
  rawQtys: Record<string, number>; // The quantity parsed from the log
  specs: Record<string, string>;
  models: Record<string, string>;
}

const ENUM_OPTIONS: Record<string, { specs: string[]; models: string[] }> = {
  gpu: {
    specs: ['NVIDIA A100 80GB x8', 'NVIDIA H100 80GB x8', 'NVIDIA L40S x4'],
    models: ['A100-PG150-S01 x8', 'H100-PG520-S01 x8', 'L40S-NVLink-V1']
  },
  cpu: {
    specs: ['Intel Xeon 8358 x2', 'Intel Xeon Platinum 8480C x2', 'AMD EPYC 9654 x2'],
    models: ['Intel-8358-Standard-V2', 'Intel-8480C-QS', 'AMD-EPYC-9654-Retail']
  },
  memory: {
    specs: ['256GB (32GB x8)', '1024GB (64GB x16)'],
    models: ['Samsung-DDR4-3200 x8', 'Hynix-DDR5-4800 x16']
  },
  networkCard: {
    specs: ['100G Dual Port x1', '25G Quad Port x1'],
    models: ['Mellanox-CX6-VPI', 'Mellanox-CX4-LX']
  },
  harddisk: {
    specs: ['2TB SATA x2', '8TB SAS x12'],
    models: ['ST2000-NM001', 'Seagate-Exos-X18']
  },
  ssd: {
    specs: ['3.84TB NVMe x2', '7.68TB NVMe x1'],
    models: ['Samsung-PM1733', 'Micron-7450-Pro']
  },
  raid: {
    specs: ['RAID 1', 'RAID 10'],
    models: ['9460-16i-Primary', '9361-8i-Adapter']
  },
  fpga: {
    specs: ['Xilinx Alveo U250 x1'],
    models: ['U250-PQ123']
  }
};

const CATEGORIES = [
  { id: 'gpu', label: 'GPU', icon: <Layout size={12} className="text-indigo-400" /> },
  { id: 'cpu', label: 'CPU', icon: <Cpu size={12} className="text-blue-400" /> },
  { id: 'memory', label: '内存', icon: <Settings2 size={12} className="text-purple-400" /> },
  { id: 'networkCard', label: '网卡', icon: <Layout size={12} className="text-emerald-400" /> },
  { id: 'harddisk', label: '硬盘', icon: <HardDrive size={12} className="text-amber-400" /> },
  { id: 'ssd', label: 'SSD', icon: <HardDrive size={12} className="text-teal-400" /> },
  { id: 'raid', label: 'RAID', icon: <Settings2 size={12} className="text-slate-400" /> },
  { id: 'fpga', label: 'FPGA', icon: <Cpu size={12} className="text-rose-400" /> },
];

const isAbnormal = (str: string) => {
  if (!str || str.trim() === '' || str.trim() === '-') return false;
  const lower = str.toLowerCase();
  return lower.includes('err:') || lower.includes('unknown') || lower.includes('mismatch') || lower.includes('bad');
};

const EditableCell: React.FC<{
  value: string;
  options: string[];
  onChange: (val: string) => void;
  placeholder?: string;
  isMono?: boolean;
}> = ({ value, options, onChange, placeholder = "请选择...", isMono }) => {
  const [isCustom, setIsCustom] = useState(!options.includes(value) && value !== "");
  const abnormal = isAbnormal(value);

  return (
    <div className="relative flex-1">
      {isCustom ? (
        <div className="relative">
          <input
            autoFocus
            type="text"
            value={value}
            onChange={(e) => onChange(e.target.value)}
            className={`w-full px-3 py-1.5 text-[11px] border rounded-lg focus:outline-none focus:ring-2 pr-7 transition-all ${
              abnormal ? 'bg-rose-50 border-rose-300 text-rose-700 focus:ring-rose-200' : 'bg-white border-blue-200 focus:ring-blue-100'
            } ${isMono ? 'font-mono' : ''}`}
          />
          <button onClick={() => setIsCustom(false)} className="absolute right-1 top-1/2 -translate-y-1/2 p-1 text-gray-400 hover:text-blue-500">
            <X size={10} />
          </button>
        </div>
      ) : (
        <div className="relative">
          <select
            value={value}
            onChange={(e) => e.target.value === "__CUSTOM__" ? setIsCustom(true) : onChange(e.target.value)}
            className={`w-full px-3 py-1.5 pr-6 text-[11px] border rounded-lg appearance-none cursor-pointer focus:outline-none focus:ring-2 transition-all ${
              abnormal ? 'bg-rose-50 border-rose-200 text-rose-600 focus:ring-rose-100 font-bold' : 'bg-white border-gray-200 focus:ring-blue-100 hover:border-blue-300'
            } ${isMono ? 'font-mono' : ''}`}
          >
            <option value="" disabled>{placeholder}</option>
            {options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            {!options.includes(value) && value !== "" && <option value={value}>{value}</option>}
            <option value="__CUSTOM__" className="text-blue-600 font-bold">+ 自定义输入</option>
          </select>
          <div className="absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
            <ChevronDown size={12} />
          </div>
        </div>
      )}
    </div>
  );
};

export const ImportModal: React.FC<{ isOpen: boolean; onClose: () => void; onApply: (configs: ParsedConfig[]) => void }> = ({ isOpen, onClose, onApply }) => {
  const [step, setStep] = useState(1);
  const [isParsing, setIsParsing] = useState(false);
  const [parsedConfigs, setParsedConfigs] = useState<ParsedConfig[]>([]);
  const [selectedConfigIds, setSelectedConfigIds] = useState<Set<string>>(new Set());
  const fileInputRef = useRef<HTMLInputElement>(null);
  const snFileInputRef = useRef<HTMLInputElement>(null);
  const [currentActiveConfigId, setCurrentActiveConfigId] = useState<string | null>(null);

  const selectedConfigs = useMemo(() => parsedConfigs.filter(c => selectedConfigIds.has(c.id)), [parsedConfigs, selectedConfigIds]);

  if (!isOpen) return null;

  const handleFileUpload = () => {
    setIsParsing(true);
    setTimeout(() => {
      const mockParsed: ParsedConfig[] = [
        {
          id: 'CFG-2024-001',
          sourceFiles: ['pxe_log_node1.txt'],
          suggestedSNs: ['SN-1001', 'SN-1002'],
          targetSNs: ['SN-1001', 'SN-1002'],
          rawIds: {
            gpu: 'NV-ID-A100-SXM4',
            cpu: 'GenuineIntel-Family-6-Model-106',
            memory: 'PN: M393A4K40CB2-CT7',
            networkCard: 'PCI-15B3-1017',
            harddisk: 'ST2000NM001',
            ssd: 'UNKNOWN_ID_SSD_09X',
            raid: 'AVAGO-MegaRAID-9460',
            fpga: '-'
          },
          rawQtys: {
            gpu: 8,
            cpu: 2,
            memory: 16,
            networkCard: 1,
            harddisk: 2,
            ssd: 4,
            raid: 1,
            fpga: 0
          },
          specs: {
            gpu: 'NVIDIA A100 80GB x8',
            cpu: 'Intel Xeon 8358 x2',
            memory: '1024GB (64GB x16)',
            networkCard: '100G Dual Port x1',
            harddisk: '2TB SATA x2',
            ssd: 'ERR: Unknown Mapping',
            raid: 'RAID 1',
            fpga: '-'
          },
          models: {
            gpuModel: 'A100-PG150-S01 x8',
            cpuModel: 'Intel-8358-Standard-V2',
            memoryModel: 'Samsung-DDR4-3200 x16',
            networkCardModel: 'Mellanox-CX6-VPI',
            harddiskModel: 'ST2000-NM001 x2',
            ssdModel: 'ERR: Unmapped Part',
            raidModel: '9460-16i-Primary',
            fpgaModel: '-'
          }
        }
      ];
      setParsedConfigs(mockParsed);
      setSelectedConfigIds(new Set(mockParsed.map(c => c.id)));
      setIsParsing(false);
      setStep(2);
    }, 1200);
  };

  const handleSNFileUpload = (e: React.ChangeEvent<HTMLInputElement>, configId: string) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const sns = (event.target?.result as string).split(/[\s,;]+/).filter(Boolean);
      updateConfig(configId, { targetSNs: sns });
      e.target.value = '';
    };
    reader.readAsText(file);
  };

  const updateConfig = (id: string, updates: Partial<ParsedConfig>) => {
    setParsedConfigs(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const updateNested = (id: string, type: 'specs' | 'models', field: string, value: string) => {
    setParsedConfigs(prev => prev.map(c => c.id === id ? { ...c, [type]: { ...(c[type] as any), [field]: value } } : c));
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white w-[1280px] max-h-[94vh] rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden border border-white">
        {/* Header */}
        <div className="px-10 py-7 border-b border-gray-100 bg-gray-50/50 flex items-center justify-between">
          <div className="flex items-center gap-5">
            <div className="p-4 bg-indigo-600 text-white rounded-3xl shadow-xl shadow-indigo-100">
              <Upload size={24} />
            </div>
            <div>
              <h3 className="font-bold text-gray-900 text-lg">导入配置文件</h3>
              <p className="text-[12px] text-gray-500 font-medium">系统将自动核对抓取数据 (Part ID) 与库中对应的规格 (Spec) 和型号 (Model)</p>
            </div>
          </div>
          <button onClick={onClose} className="p-2.5 hover:bg-gray-200 rounded-full text-gray-400 transition-colors"><X size={24} /></button>
        </div>

        {/* Steps Navigation */}
        <div className="flex bg-white px-16 py-6 border-b border-gray-50 shadow-sm justify-between">
          {[
            { n: 1, l: '文件解析' },
            { n: 2, l: '规格与 Model 映射核对' },
            { n: 3, l: '资产应用' }
          ].map((s, i) => (
            <React.Fragment key={s.n}>
              <div className={`flex items-center gap-4 ${step >= s.n ? 'text-indigo-600' : 'text-gray-300'}`}>
                <div className={`w-9 h-9 rounded-full flex items-center justify-center text-sm font-bold transition-all ${step >= s.n ? 'bg-indigo-600 text-white shadow-lg' : 'bg-gray-100 border border-gray-200'}`}>{s.n}</div>
                <span className="text-[13px] font-bold whitespace-nowrap">{s.l}</span>
