  if (!isOpen) return null;

  const handleFileUpload = () => {
    setIsParsing(true);
    setTimeout(() => {
      const allSNs = Array.from({ length: 100 }, (_, i) => `SN-IMPORT-${2000 + i}`);

      const configA: ParsedConfig = {
