                  <div className="flex gap-4">
                    <div className="px-5 py-2.5 bg-emerald-50 text-emerald-600 rounded-2xl border border-emerald-100 flex items-center gap-2 text-[11px] font-bold">
                       <CheckCircle size={14} /> 已识别模板: 2 组
                    </div>
                    <div className={`px-5 py-2.5 rounded-2xl border flex items-center gap-2 text-[11px] font-bold ${totalUnmappedCount > 0 ? 'bg-rose-50 text-rose-600 border-rose-100 animate-pulse' : 'bg-indigo-50 text-indigo-600 border-indigo-100'}`}>
                       <AlertTriangle size={14} /> 待对齐 Part ID: {totalUnmappedCount} 项
                    </div>
                  </div>
                </div>

                {/* UNMAPPED SUMMARY BY ACCESSORY TYPE */}
                <div className="space-y-6">
                  <h5 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
                    <Layers size={14} /> 按配件类型聚合的待对齐项
                  </h5>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                    {Object.entries(unmappedSummary).map(([catId, summary]) => {
                      const hasIssues = summary.issues.length > 0;
                      return (
                        <div key={catId} className={`relative flex flex-col p-5 rounded-[2rem] border transition-all ${hasIssues ? 'bg-rose-50/50 border-rose-200' : 'bg-slate-50/30 border-slate-100 opacity-60'}`}>
