                                <span className="text-[12px] font-bold text-slate-700">{summary.label}</span>
                              </div>
                              {hasIssues ? (
                                <span className="px-2 py-0.5 bg-rose-500 text-white text-[10px] font-bold rounded-lg shadow-lg shadow-rose-200">
