        {/* Footer Actions */}
        <div className="px-12 py-8 border-t border-gray-100 bg-gray-50/50 flex items-center justify-between">
          <div className="flex items-center gap-4 text-gray-400">
            <AlertTriangle size={24} className="text-amber-500" />
            <span className="text-[11px] font-bold leading-relaxed uppercase tracking-tight max-w-md">同步后系统将强制覆盖目标资产硬件快照。厂商指派将直接决定 Spec 信息准确性。</span>
          </div>
          <div className="flex gap-5">
            <button onClick={onClose} className="px-12 py-4 text-xs font-bold text-gray-500 hover:bg-slate-200 rounded-2xl transition-all">取消导入</button>
            {step > 1 && <button onClick={() => setStep(step - 1)} className="px-12 py-4 text-xs font-bold text-indigo-600 border border-indigo-200 rounded-2xl hover:bg-indigo-50 transition-all">返回上一步</button>}
            {step < 3 ? (
              <button 
                onClick={() => setStep(step + 1)} 
                disabled={step === 1 && (!hasUploaded || unassignedCount > 0)}
                className={`flex items-center gap-3 px-16 py-4 text-xs font-bold text-white rounded-2xl shadow-2xl transition-all ${step === 1 && (!hasUploaded || unassignedCount > 0) ? 'bg-gray-300 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-700 active:scale-95 shadow-indigo-100'}`}
              >
                {step === 1 ? '分配完成，核对规格' : '下一步: 完成预览'} <ChevronRight size={20} />
              </button>
            ) : (
              <button onClick={() => { onApply(selectedConfigs); onClose(); }} className="flex items-center gap-3 px-20 py-4 text-xs font-bold text-white bg-green-600 rounded-2xl shadow-2xl shadow-green-100 hover:bg-green-700 active:scale-95 transition-all">
                <Save size={20} /> 立即执行同步任务
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

