          {step === 1 && hasUploaded && (
            <div className="h-1.5 w-full bg-slate-50 relative">
              <div className="absolute inset-y-0 left-0 bg-indigo-600 transition-all duration-500 ease-out" style={{ width: `${progressPercent}%` }} />
            </div>
          )}
