        {/* Main Content Area */}
        <div className="flex-1 overflow-auto p-10 bg-slate-50/30 custom-scrollbar min-h-[550px]">
          {step === 1 && (
            <div className="h-full flex flex-col items-center justify-start gap-10">
              {isParsing ? (
