import React, { useState, useMemo } from 'react';
import { ChevronDown, ChevronUp, AlertTriangle, FileText, Settings2, Paperclip } from 'lucide-react';
import { ServerAsset } from '../types';
import { COLUMNS } from '../constants';

const isAbnormalString = (model: string): boolean => {
  const lower = model.toLowerCase();
  return lower.includes('err:') || lower.includes('unknown') || lower.includes('mismatch') || lower.includes('bad');
};

const checkRowAbnormality = (row: ServerAsset): boolean => {
  const modelKeys: (keyof ServerAsset)[] = [
    'cpuModel', 'gpuModel', 'memoryModel', 'networkCardModel', 'harddiskModel', 'ssdModel', 'raidModel', 'fpgaModel'
  ];
  return modelKeys.some(key => isAbnormalString(String(row[key])));
};

const ComponentDetail: React.FC<{ spec: string; models: string }> = ({ spec, models }) => {
  if (!spec || spec === '-') return <span className="text-gray-300">-</span>;

  const specGroups = spec.split('|').map(s => s.trim());
  const modelGroups = models.split('|').map(m => m.trim());

  return (
    <div className="flex flex-col py-1 gap-2.5 max-w-full">
      {specGroups.map((currentSpec, idx) => {
        const currentModelStr = modelGroups[idx] || '';
        const modelList = currentModelStr.split(';').map(m => m.trim()).filter(Boolean);

        return (
          <div key={idx} className="flex flex-col gap-1 group/spec">
            <div 
              className="font-bold text-gray-800 text-[11px] leading-tight border-b border-gray-100 pb-0.5 group-hover/spec:text-blue-700 transition-colors"
              title={currentSpec}
            >
              {currentSpec}
            </div>
            <div className="flex flex-col gap-0.5 pl-1.5 border-l-2 border-blue-100">
              {modelList.length > 0 ? (
                modelList.map((m, mIdx) => {
                  const abnormal = isAbnormalString(m);
                  return (
                    <div 
                      key={mIdx} 
                      className={`flex items-center gap-1 text-[10px] leading-relaxed font-mono truncate px-1 rounded-sm transition-colors ${
                        abnormal 
                          ? 'text-red-600 bg-red-50 border border-red-100 animate-pulse font-semibold' 
                          : 'text-gray-500 hover:text-gray-800'
                      }`}
                      title={abnormal ? `检测到异常数据: ${m}` : m}
                    >
                      {abnormal && <AlertTriangle size={10} className="shrink-0" />}
                      <span className="truncate">{m}</span>
                    </div>
                  );
                })
              ) : (
                <div className="text-[10px] text-gray-300 italic">No Model Data</div>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
};

interface TableProps {
  data: ServerAsset[];
  highlightedSNs: Set<string>;
  onShowLog: (server: ServerAsset) => void;
  onUpdateConfig: (server: ServerAsset) => void;
  visibleKeys: Set<string>;
}

export const ServerTable: React.FC<TableProps> = ({ data, highlightedSNs, onShowLog, onUpdateConfig, visibleKeys }) => {
  const [selectedRows, setSelectedRows] = useState<Set<string>>(new Set());

  const activeColumns = useMemo(() => {
    return COLUMNS.filter(col => visibleKeys.has(col.key));
  }, [visibleKeys]);

  const toggleSelectAll = () => {
    if (selectedRows.size === data.length) {
      setSelectedRows(new Set());
    } else {
      setSelectedRows(new Set(data.map(d => d.id)));
    }
  };

  const toggleRow = (id: string) => {
    const newSelected = new Set(selectedRows);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedRows(newSelected);
  };

  const totalWidth = activeColumns.reduce((sum, col) => {
    const w = parseInt(col.width.replace('w-', '')) * 4; // Approx convert tailwind w-X to pixels
    return sum + (isNaN(w) ? 200 : w);
  }, 40);

  return (
    <div className="flex-1 overflow-auto bg-white table-container relative">
      <table className="w-full border-collapse table-fixed text-[11px] leading-tight" style={{ minWidth: `${totalWidth}px` }}>
        <thead>
          <tr className="bg-gray-100 text-gray-700 uppercase tracking-wider font-semibold border-b border-gray-200 shadow-sm">
            <th className="w-10 px-2 py-3 border-r border-gray-200 sticky top-0 bg-gray-100 z-30 text-center">
              <input 
                type="checkbox" 
                className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 cursor-pointer" 
                checked={selectedRows.size === data.length && data.length > 0}
                onChange={toggleSelectAll}
              />
            </th>
            {activeColumns.map((col) => (
              <th 
                key={col.key} 
                className={`${col.width} px-3 py-3 border-r border-gray-200 text-left sticky top-0 bg-gray-100 z-20 hover:bg-gray-200 cursor-pointer group whitespace-nowrap`}
              >
                <div className="flex items-center justify-between">
                  <span className="truncate">{col.label}</span>
                  {col.key !== 'actions' && (
                    <div className="flex flex-col opacity-20 group-hover:opacity-100 transition-opacity">
                      <ChevronUp size={8} className="mb-[-2px]" />
                      <ChevronDown size={8} />
                    </div>
                  )}
                </div>
              </th>
            ))}
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-100">
          {data.map((row) => {
            const hasAbnormal = checkRowAbnormality(row);
            const isJustUpdated = highlightedSNs.has(row.sn);
            const canUpdateConfig = row.status === '已到货';

            return (
              <tr 
                key={row.id} 
                className={`transition-colors duration-500 ${isJustUpdated ? 'bg-yellow-50' : 'hover:bg-blue-50/40'} ${selectedRows.has(row.id) ? 'bg-blue-50' : ''}`}
              >
                <td className="px-2 py-2 border-r border-gray-200 text-center align-top pt-4">
                  <input 
                    type="checkbox" 
                    className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 cursor-pointer" 
                    checked={selectedRows.has(row.id)}
                    onChange={() => toggleRow(row.id)}
                  />
                </td>
                {activeColumns.map((col) => {
                  const isConfigCol = !!(col as any).modelKey;
                  const value = row[col.key as keyof typeof row];
                  const modelValue = isConfigCol ? row[(col as any).modelKey as keyof typeof row] : null;

                  return (
                    <td 
                      key={col.key} 
                      className="px-3 py-3 border-r border-gray-200 align-top"
                    >
                      {isConfigCol ? (
                        <ComponentDetail spec={String(value)} models={String(modelValue)} />
                      ) : col.key === 'status' ? (
                        <div className="pt-1">
                          <span className={`inline-block px-2 py-0.5 rounded-sm font-bold text-[10px] ${
                            row.status === '正常运行' ? 'bg-green-100 text-green-700' : 
                            row.status === '机器下架' ? 'bg-red-100 text-red-700' : 
                            row.status === '维护中' ? 'bg-orange-100 text-orange-700' : 
                            row.status === '已到货' ? 'bg-blue-100 text-blue-700 border border-blue-200' :
                            'bg-gray-100 text-gray-700'
                          }`}>
                            {row.status}
                          </span>
                        </div>
                      ) : col.key === 'arrivalBatch' ? (
                        <div className="pt-1 text-gray-600 font-medium">
                          {String(value)}
                        </div>
                      ) : col.key === 'source' ? (
                        <div className="pt-1">
                          <span className="inline-block px-1.5 py-0.5 rounded-sm bg-gray-100 text-gray-600 border border-gray-200 font-medium text-[10px]">
                            {String(value)}
                          </span>
                        </div>
                      ) : col.key === 'configType' ? (
                        <div className="pt-1">
                          <span className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded-sm font-medium transition-all ${
                            row.configType === '改配配置' 
                              ? 'bg-amber-100 text-amber-700 border border-amber-200' 
                              : (hasAbnormal 
                                  ? 'bg-red-100 text-red-700 border border-red-200 ring-1 ring-red-100' 
                                  : 'bg-slate-100 text-slate-700 border border-slate-200')
                          }`}>
                            {hasAbnormal && row.configType === '到货配置' && <AlertTriangle size={10} className="text-red-600" />}
                            {row.configType}
                          </span>
                        </div>
                      ) : col.key === 'configSource' ? (
                        <div className="pt-1">
                          <span className={`inline-block px-1.5 py-0.5 rounded-sm font-medium ${
                            row.configSource === '人工更新' ? 'bg-blue-50 text-blue-600 border border-blue-100' : 
                            row.configSource === 'PXE抓取' ? 'bg-purple-50 text-purple-600 border border-purple-100' : 
                            row.configSource === '监控抓取' ? 'bg-teal-50 text-teal-600 border border-teal-100' : 
                            'bg-rose-50 text-rose-600 border border-rose-100'
                          }`}>
                            {row.configSource}
                          </span>
                        </div>
                      ) : col.key === 'attachments' ? (
                        <div className="flex flex-col gap-1 pt-1 overflow-hidden">
                          {row.attachments && row.attachments.length > 0 ? (
                            row.attachments.map((file, fIdx) => (
                              <div key={fIdx} className="flex items-center gap-1.5 px-2 py-0.5 bg-indigo-50 border border-indigo-100 rounded-sm group/file hover:bg-indigo-100 transition-colors cursor-pointer max-w-full">
                                <Paperclip size={10} className="text-indigo-400 shrink-0" />
                                <span className="text-[10px] text-indigo-700 font-medium truncate" title={file}>{file}</span>
                              </div>
                            ))
                          ) : (
                            <span className="text-gray-300 px-2 italic text-[10px]">无附件</span>
                          )}
                        </div>
                      ) : col.key === 'updatedAt' ? (
                        <div className="pt-1 font-mono text-gray-500 whitespace-nowrap">
                          {String(value)}
                        </div>
                      ) : col.key === 'isGpuServer' ? (
                        <div className="pt-1 text-center font-bold">
                          <span className={row.isGpuServer === '是' ? 'text-blue-600' : 'text-gray-300'}>
                            {row.isGpuServer}
                          </span>
                        </div>
                      ) : col.key === 'actions' ? (
                        <div className="flex flex-col gap-1.5 pt-0.5">
                          <button 
                            className="flex items-center gap-1.5 px-2 py-1 text-blue-600 hover:bg-blue-50 rounded transition-colors group/btn"
                            onClick={(e) => { e.stopPropagation(); onShowLog(row); }}
                          >
                            <FileText size={12} className="group-hover/btn:scale-110 transition-transform" />
                            <span>日志</span>
                          </button>
                          <button 
                            disabled={!canUpdateConfig}
                            title={!canUpdateConfig ? '仅“已到货”状态的机器可更新配置' : ''}
                            className={`flex items-center gap-1.5 px-2 py-1 rounded transition-colors group/btn ${
                              canUpdateConfig 
                                ? 'text-indigo-600 hover:bg-indigo-50' 
                                : 'text-gray-300 cursor-not-allowed bg-gray-50'
                            }`}
                            onClick={(e) => { e.stopPropagation(); onUpdateConfig(row); }}
                          >
                            <Settings2 size={12} className={canUpdateConfig ? "group-hover/btn:scale-110 transition-transform" : ""} />
                            <span>更新配置</span>
                          </button>
                        </div>
                      ) : (
                        <div className="pt-1 font-mono text-gray-800 break-all">{String(value)}</div>
                      )}
                    </td>
                  );
                })}
              </tr>
            );
          })}
        </tbody>
      </table>

      <div className="fixed inset-0 pointer-events-none opacity-[0.03] select-none flex flex-wrap justify-around items-around z-0 overflow-hidden">
        {Array.from({ length: 40 }).map((_, i) => (
          <div key={i} className="transform -rotate-45 text-2xl font-bold p-20">兰义丰 5449</div>
        ))}
      </div>
    </div>
  );
};

import React from 'react';
import { X, Check, RotateCcw, Layout } from 'lucide-react';
import { COLUMNS } from '../constants';

interface ColumnConfigModalProps {
  isOpen: boolean;
  onClose: () => void;
  visibleKeys: Set<string>;
  onChange: (keys: Set<string>) => void;
}

export const ColumnConfigModal: React.FC<ColumnConfigModalProps> = ({ isOpen, onClose, visibleKeys, onChange }) => {
  if (!isOpen) return null;

  const toggleColumn = (key: string) => {
    const next = new Set(visibleKeys);
    if (next.has(key)) {
      if (next.size > 1) next.delete(key); // Ensure at least one column remains
    } else {
      next.add(key);
    }
    onChange(next);
  };

  const resetToDefault = () => {
    onChange(new Set(COLUMNS.map(c => c.key)));
  };

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white w-[500px] max-h-[85vh] rounded-2xl shadow-2xl flex flex-col overflow-hidden border border-gray-100">
        <div className="px-6 py-5 border-b border-gray-100 bg-gray-50 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-indigo-100 text-indigo-600 rounded-xl shadow-sm">
              <Layout size={20} />
            </div>
            <div>
              <h3 className="font-bold text-gray-800 text-sm">设置显示字段</h3>
              <p className="text-[10px] text-gray-500 font-medium">勾选您希望在资产列表中看到的字段</p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-400 transition-colors">
            <X size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 bg-white custom-scrollbar-thin">
          <div className="grid grid-cols-2 gap-3">
            {COLUMNS.map(col => (
              <div 
                key={col.key}
                onClick={() => toggleColumn(col.key)}
                className={`flex items-center gap-3 px-4 py-3 rounded-xl border transition-all cursor-pointer group ${
                  visibleKeys.has(col.key) 
                    ? 'bg-indigo-50 border-indigo-200 shadow-sm' 
                    : 'bg-white border-gray-100 hover:border-gray-200 text-gray-400'
                }`}
              >
                <div className={`w-5 h-5 rounded-md border flex items-center justify-center transition-colors ${
                  visibleKeys.has(col.key) ? 'bg-indigo-600 border-indigo-600' : 'border-gray-200 group-hover:border-gray-300'
                }`}>
                  {visibleKeys.has(col.key) && <Check size={12} className="text-white" />}
                </div>
                <span className={`text-[12px] font-bold ${visibleKeys.has(col.key) ? 'text-indigo-900' : 'text-gray-500'}`}>
                  {col.label}
                </span>
              </div>
            ))}
          </div>
        </div>

        <div className="px-6 py-4 bg-gray-50 border-t border-gray-100 flex items-center justify-between">
          <button 
            onClick={resetToDefault}
            className="flex items-center gap-2 px-4 py-2 text-[11px] font-bold text-gray-500 hover:bg-white hover:shadow-sm rounded-lg transition-all"
          >
            <RotateCcw size={14} /> 恢复默认显示
          </button>
          <button 
            onClick={onClose}
            className="px-8 py-2.5 bg-indigo-600 text-white rounded-xl text-[12px] font-bold shadow-lg shadow-indigo-100 hover:bg-indigo-700 active:scale-95 transition-all"
          >
            完成设置
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Toolbar } from './components/Toolbar';
import { ServerTable } from './components/ServerTable';
import { ImportModal } from './components/ImportModal';
import { LogModal } from './components/LogModal';
import { SingleUpdateModal } from './components/SingleUpdateModal';
import { AdvancedQueryPanel } from './components/AdvancedQueryPanel';
import { ColumnConfigModal } from './components/ColumnConfigModal';
import { MOCK_DATA, MOCK_LOGS, COLUMNS } from './constants';
import { ActionType, ServerAsset, LogEntry, FilterState } from './types';

const App: React.FC = () => {
  const [data, setData] = useState<ServerAsset[]>(MOCK_DATA);
  const [logs, setLogs] = useState<LogEntry[]>(MOCK_LOGS);

  const [isImportOpen, setIsImportOpen] = useState(false);
  const [isLogOpen, setIsLogOpen] = useState(false);
  const [isUpdateOpen, setIsUpdateOpen] = useState(false);
  const [isQueryPanelOpen, setIsQueryPanelOpen] = useState(false);
  const [isColumnConfigOpen, setIsColumnConfigOpen] = useState(false);

  const [activeServer, setActiveServer] = useState<ServerAsset | null>(null);
  const [lastUpdatedSNs, setLastUpdatedSNs] = useState<Set<string>>(new Set());
  const [filters, setFilters] = useState<FilterState | null>(null);

  // 初始化可见列，支持 localStorage 持久化
  const [visibleKeys, setVisibleKeys] = useState<Set<string>>(() => {
    const saved = localStorage.getItem('server_asset_visible_columns');
    if (saved) {
      try {
        return new Set(JSON.parse(saved));
      } catch (e) {
        return new Set(COLUMNS.map(c => c.key));
      }
    }
    return new Set(COLUMNS.map(c => c.key));
  });

  useEffect(() => {
    localStorage.setItem('server_asset_visible_columns', JSON.stringify(Array.from(visibleKeys)));
  }, [visibleKeys]);

  // 获取所有唯一的到货批次
  const availableBatches = useMemo(() => {
    const batches = new Set<string>();
    MOCK_DATA.forEach(item => batches.add(item.arrivalBatch));
    return Array.from(batches).sort();
  }, []);

  // 辅助函数：解析批量输入字符串
  const parseBulkInput = (input: string) => {
    if (!input) return [];
    return input.split(/[\s,;\n]+/).filter(Boolean).map(s => s.trim());
  };

  // 过滤后的数据
  const filteredData = useMemo(() => {
    if (!filters) return data;

    const snBulkList = parseBulkInput(filters.snBulk);
    const batchBulkList = parseBulkInput(filters.arrivalBatchBulk);

    return data.filter(item => {
      // 标准搜索
      if (filters.sn && !item.sn.toLowerCase().includes(filters.sn.toLowerCase())) return false;
      if (filters.hostname && !item.hostname.toLowerCase().includes(filters.hostname.toLowerCase())) return false;
      if (filters.statuses.length > 0 && !filters.statuses.includes(item.status)) return false;
      if (filters.isGpuServer !== '全部' && item.isGpuServer !== filters.isGpuServer) return false;
      if (filters.sources.length > 0 && !filters.sources.includes(item.source)) return false;
      if (filters.arrivalBatches.length > 0 && !filters.arrivalBatches.includes(item.arrivalBatch)) return false;
      if (filters.configTypes.length > 0 && !filters.configTypes.includes(item.configType)) return false;
      if (filters.configSources.length > 0 && !filters.configSources.includes(item.configSource)) return false;

      // 批量搜索逻辑
      if (snBulkList.length > 0 && !snBulkList.some(sn => item.sn.toLowerCase().includes(sn.toLowerCase()))) return false;
      if (batchBulkList.length > 0 && !batchBulkList.some(batch => item.arrivalBatch.toLowerCase().includes(batch.toLowerCase()))) return false;

      return true;
    });
  }, [data, filters]);

  const handleToolbarAction = (type: ActionType) => {
    if (type === ActionType.IMPORT_CONFIG) {
      setIsImportOpen(true);
    } else if (type === ActionType.QUERY) {
      setIsQueryPanelOpen(!isQueryPanelOpen);
    } else if (type === ActionType.CONFIG) {
      setIsColumnConfigOpen(true);
    }
  };

  const handleShowLog = (server: ServerAsset) => {
    setActiveServer(server);
    setIsLogOpen(true);
  };

  const handleUpdateConfig = (server: ServerAsset) => {
    setActiveServer(server);
    setIsUpdateOpen(true);
  };

  const handleAdvancedSearch = (newFilters: FilterState) => {
    setFilters(newFilters);
  };

  const handleSaveSingleConfig = (sn: string, updates: Partial<ServerAsset>) => {
    const now = new Date().toLocaleString();
    const serverIndex = data.findIndex(s => s.sn === sn);
    if (serverIndex === -1) return;

    const oldServer = data[serverIndex];
    const newData = [...data];

    // 记录变更
    const changeDetails: LogEntry['details'] = [];
    Object.keys(updates).forEach(key => {
      const k = key as keyof ServerAsset;
      if (updates[k] !== oldServer[k]) {
        changeDetails.push({
          field: String(k),
          before: String(oldServer[k] || ''),
          after: String(updates[k] || '')
        });
      }
    });

    if (changeDetails.length > 0) {
      const newLog: LogEntry = {
        id: `L-${Date.now()}`,
        sn: sn,
        operator: '兰义丰',
        action: '手动更新配置',
        details: changeDetails,
        timestamp: now
      };
      setLogs([newLog, ...logs]);
    }

    newData[serverIndex] = {
      ...oldServer,
      ...updates,
      configSource: '人工更新',
      configType: '改配配置',
      updatedAt: now
    };

    setData(newData);
    setLastUpdatedSNs(new Set([sn]));
    setTimeout(() => setLastUpdatedSNs(new Set()), 4000);
  };

  const handleApplyConfig = (configs: any[]) => {
    const now = new Date().toLocaleString();
    const updatedSNs = new Set<string>();

    const snMap = new Map<string, any>();
    configs.forEach(cfg => {
      cfg.targetSNs.forEach((sn: string) => {
        snMap.set(sn.trim(), cfg);
        updatedSNs.add(sn.trim());
      });
    });

    const newData = data.map(item => {
      const cfg = snMap.get(item.sn);
      if (cfg) {
        return {
          ...item,
          ...cfg.specs,
          ...cfg.models,
          attachments: cfg.sourceFiles,
          configSource: '改配' as const,
          configType: '改配配置' as const,
          updatedAt: now
        };
      }
      return item;
    });

    setData(newData);
    setLastUpdatedSNs(updatedSNs);
    setTimeout(() => setLastUpdatedSNs(new Set()), 4000);
  };

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-slate-50">
      <Toolbar onAction={handleToolbarAction} />

      <AdvancedQueryPanel 
        isOpen={isQueryPanelOpen} 
        onClose={() => setIsQueryPanelOpen(false)}
        onSearch={handleAdvancedSearch}
        batches={availableBatches}
      />

      <main className="flex-1 flex flex-col relative">
        <ServerTable 
          data={filteredData} 
          highlightedSNs={lastUpdatedSNs} 
          onShowLog={handleShowLog}
          onUpdateConfig={handleUpdateConfig}
          visibleKeys={visibleKeys}
        />

        {/* Footer */}
        <footer className="h-8 bg-white border-t border-gray-200 flex items-center justify-between px-4 text-[11px] text-gray-500 z-10 shadow-inner">
          <div className="flex items-center gap-4">
            <span>共 {filteredData.length} 条记录 / 总计 {data.length} 条</span>
            <span>已选 0 条</span>
          </div>
          <div className="flex items-center gap-2">
            <button className="px-2 py-0.5 border border-gray-300 rounded hover:bg-gray-50">上一页</button>
            <span className="font-bold text-blue-600 px-2 py-0.5 bg-blue-50 rounded">1</span>
            <button className="px-2 py-0.5 border border-gray-300 rounded hover:bg-gray-50">下一页</button>
          </div>
        </footer>
      </main>

      <ImportModal 
        isOpen={isImportOpen} 
        onClose={() => setIsImportOpen(false)} 
        onApply={handleApplyConfig}
      />

      <LogModal 
        isOpen={isLogOpen} 
        onClose={() => setIsLogOpen(false)} 
        sn={activeServer?.sn || ''}
        logs={logs.filter(l => l.sn === activeServer?.sn)}
      />

      <SingleUpdateModal 
        isOpen={isUpdateOpen} 
        onClose={() => setIsUpdateOpen(false)} 
        server={activeServer}
        onSave={handleSaveSingleConfig}
      />

      <ColumnConfigModal 
        isOpen={isColumnConfigOpen}
        onClose={() => setIsColumnConfigOpen(false)}
        visibleKeys={visibleKeys}
        onChange={setVisibleKeys}
      />

      <div className="fixed bottom-12 right-6 flex flex-col gap-2 z-50">
        <button className="w-10 h-10 bg-blue-500 text-white rounded-full shadow-lg flex items-center justify-center hover:bg-blue-600 transition-all hover:scale-110 active:scale-95 border-2 border-white">
          <span className="text-[10px] text-center font-bold leading-tight">问题<br/>反馈</span>
        </button>
      </div>
    </div>
  );
};

