      const newSns = (event.target?.result as string).split(/[\s,;]+/).filter(Boolean);
      setParsedConfigs(prev => prev.map(c => c.id === configId ? { ...c, additionalSNs: [...new Set([...c.additionalSNs, ...newSns])] } : c));
      e.target.value = '';
