                          <div className="flex items-center gap-4">
                             <div className={`p-3 rounded-2xl ${selectedSNsInStep1.size > 0 ? 'bg-indigo-600 text-white' : 'bg-slate-200 text-slate-400'}`}><Zap size={20} /></div>
                             <div><h5 className="text-base font-black text-slate-800">指派厂商至所选资产</h5><p className="text-[12px] text-slate-500 mt-0.5">已选中 <span className="text-indigo-600 font-black">{selectedSNsInStep1.size}</span> 台服务器</p></div>
                          </div>

                          <div className="space-y-4">
                             <div className="relative group">
                                <Search size={16} className={`absolute left-4 top-1/2 -translate-y-1/2 transition-colors ${brandSearchTerm ? 'text-indigo-500' : 'text-slate-300'}`} />
                                <input 
                                  type="text" 
                                  value={brandSearchTerm}
                                  onChange={e => setBrandSearchTerm(e.target.value)}
                                  placeholder="搜索预设厂商库..." 
                                  className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-[12px] font-bold outline-none focus:ring-4 focus:ring-indigo-50 focus:border-indigo-400 transition-all shadow-inner"
                                  disabled={selectedSNsInStep1.size === 0}
