                                     <div className="p-3 bg-white rounded-2xl shadow-sm"><Search size={24} className="text-slate-300" /></div>
                                     <p className="text-[11px] font-bold text-slate-400 leading-relaxed italic">请输入关键字筛选库中厂商</p>
