                    </div>
                  </div>
                );
              })}

              {(!configs[activeTab] || configs[activeTab]?.length === 0) && (
                <div className="py-20 text-center border-2 border-dashed border-slate-100 rounded-[2.5rem] flex flex-col items-center gap-3">
